INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,78,'Al-Hajj','وَجَٰهِدُواْ فِي ٱللَّهِ حَقَّ جِهَادِهِۦۚ هُوَ ٱجۡتَبَىٰكُمۡ وَمَا جَعَلَ عَلَيۡكُمۡ فِي ٱلدِّينِ مِنۡ حَرَجࣲۚ مِّلَّةَ أَبِيكُمۡ إِبۡرَٰهِيمَۚ هُوَ سَمَّىٰكُمُ ٱلۡمُسۡلِمِينَ مِن قَبۡلُ وَفِي هَٰذَا لِيَكُونَ ٱلرَّسُولُ شَهِيدًا عَلَيۡكُمۡ وَتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِۚ فَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَٱعۡتَصِمُواْ بِٱللَّهِ هُوَ مَوۡلَىٰكُمۡۖ فَنِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِيرُ','اور خدا (کی راہ) میں جہاد کرو جیسا جہاد کرنے کا حق ہے۔ اس نے تم کو برگزیدہ کیا ہے اور تم پر دین کی (کسی بات) میں تنگی نہیں کی۔ (اور تمہارے لئے) تمہارے باپ ابراہیم کا دین (پسند کیا) اُسی نے پہلے (یعنی پہلی کتابوں میں) تمہارا نام مسلمان رکھا تھا اور اس کتاب میں بھی (وہی نام رکھا ہے تو جہاد کرو) تاکہ پیغمبر تمہارے بارے میں شاہد ہوں۔ اور تم لوگوں کے مقابلے میں شاہد اور نماز پڑھو اور زکوٰة دو اور خدا کے دین کی (رسی کو) پکڑے رہو۔ وہی تمہارا دوست ہے۔ اور خوب دوست اور خوب مددگار ہے','Strive for ˹the cause of˺ Allah in the way He deserves, for ˹it is˺ He ˹Who˺ has chosen you, and laid upon you no hardship in the religion—the way of your forefather Abraham. ˹It is Allah˺ Who named you ‘the ones who submit’ ˹in the˺ earlier ˹Scriptures˺ and in this ˹Quran˺, so that the Messenger may be a witness over you, and that you may be witnesses over humanity. So establish prayer, pay alms-tax, and hold fast to Allah. He ˹alone˺ is your Guardian. What an excellent Guardian, and what an excellent Helper','ताकि तुम कामयाब हो और जो हक़ जिहाद करने का है खुदा की राह में जिहाद करो उसी नें तुमको बरगुज़ीदा किया और उमूरे दीन में तुम पर किसी तरह की सख्ती नहीं की तुम्हारे बाप इबराहीम ने मजहब को (तुम्हारा मज़हब बना दिया उसी (खुदा) ने तुम्हारा पहले ही से मुसलमान (फरमाबरदार बन्दे) नाम रखा और कुरान में भी (तो जिहाद करो) ताकि रसूल तुम्हारे मुक़ाबले में गवाह बने और तुम पाबन्दी से नामज़ पढ़ा करो और ज़कात देते रहो और खुदा ही (के एहकाम) को मज़बूत पकड़ो वही तुम्हारा सरपरस्त है तो क्या अच्छा सरपरस्त है और क्या अच्छा मददगार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,1,'Al-Muminoon','قَدۡ أَفۡلَحَ ٱلۡمُؤۡمِنُونَ','بےشک ایمان والے رستگار ہوگئے','Successful indeed are the believers','अलबत्ता वह ईमान लाने वाले रस्तगार हुए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,2,'Al-Muminoon','ٱلَّذِينَ هُمۡ فِي صَلَاتِهِمۡ خَٰشِعُونَ','جو نماز میں عجزو نیاز کرتے ہیں','those who humble themselves in prayer','जो अपनी नमाज़ों में (खुदा के सामने) गिड़गिड़ाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,3,'Al-Muminoon','وَٱلَّذِينَ هُمۡ عَنِ ٱللَّغۡوِ مُعۡرِضُونَ','اور جو بیہودہ باتوں سے منہ موڑے رہتے ہیں','those who avoid idle talk','और जो बेहूदा बातों से मुँह फेरे रहते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,4,'Al-Muminoon','وَٱلَّذِينَ هُمۡ لِلزَّكَوٰةِ فَٰعِلُونَ','اور جو زکوٰة ادا کرتے ہیں','those who pay alms-tax','और जो ज़कात (अदा) किया करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,5,'Al-Muminoon','وَٱلَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَٰفِظُونَ','اور جو اپنی شرمگاہوں کی حفاظت کرتے ہیں','those who guard their chastity','और जो (अपनी) शर्मगाहों को (हराम से) बचाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,6,'Al-Muminoon','إِلَّا عَلَىٰٓ أَزۡوَٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَإِنَّهُمۡ غَيۡرُ مَلُومِينَ','مگر اپنی بیویوں سے یا (کنیزوں سے) جو ان کی مِلک ہوتی ہیں کہ (ان سے) مباشرت کرنے سے انہیں ملامت نہیں','except with their wives or those ˹bondwomen˺ in their possession, for then they are free from blame','मगर अपनी बीबियों से या अपनी ज़र ख़रीद लौनडियों से कि उन पर हरगिज़ इल्ज़ाम नहीं हो सकता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,7,'Al-Muminoon','فَمَنِ ٱبۡتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡعَادُونَ','اور جو ان کے سوا اوروں کے طالب ہوں وہ (خدا کی مقرر کی ہوئی حد سے) نکل جانے والے ہیں','but whoever seeks beyond that are the transgressors','पस जो शख्स उसके सिवा किसी और तरीके से शहवत परस्ती की तमन्ना करे तो ऐसे ही लोग हद से बढ़ जाने वाले हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,8,'Al-Muminoon','وَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ','اور جو امانتوں اور اقراروں کو ملحوظ رکھتے ہیں','˹the believers are also˺ those who are true to their trusts and covenants','और जो अपनी अमानतों और अपने एहद का लिहाज़ रखते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,9,'Al-Muminoon','وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَوَٰتِهِمۡ يُحَافِظُونَ','اور جو نمازوں کی پابندی کرتے ہیں','and those who are ˹properly˺ observant of their prayers','और जो अपनी नमाज़ों की पाबन्दी करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,10,'Al-Muminoon','أُوْلَٰٓئِكَ هُمُ ٱلۡوَٰرِثُونَ','یہ ہی لوگ میراث حاصل کرنے والے ہیں','These are the ones who will be awarded','(आदमी की औलाद में) यही लोग सच्चे वारिस है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,11,'Al-Muminoon','ٱلَّذِينَ يَرِثُونَ ٱلۡفِرۡدَوۡسَ هُمۡ فِيهَا خَٰلِدُونَ','(یعنی) جو بہشت کی میراث حاصل کریں گے۔ اور اس میں ہمیشہ رہیں گے','Paradise as their own. They will be there forever','जो बेहश्त बरी का हिस्सा लेंगे (और) यही लोग इसमें हमेशा (जिन्दा) रहेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,12,'Al-Muminoon','وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ مِن سُلَٰلَةࣲ مِّن طِينࣲ‏','اور ہم نے انسان کو مٹی کے خلاصے سے پیدا کیا ہے','And indeed, We created humankind from an extract of clay','और हमने आदमी को गीली मिट्टी के जौहर से पैदा किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,13,'Al-Muminoon','ثُمَّ جَعَلۡنَٰهُ نُطۡفَةࣰ فِي قَرَارࣲ مَّكِينࣲ‏','پھر اس کو ایک مضبوط (اور محفوظ) جگہ میں نطفہ بنا کر رکھا','then placed each ˹human˺ as a sperm-drop in a secure place','फिर हमने उसको एक महफूज़ जगह (औरत के रहम में) नुत्फ़ा बना कर रखा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,14,'Al-Muminoon','ثُمَّ خَلَقۡنَا ٱلنُّطۡفَةَ عَلَقَةࣰ فَخَلَقۡنَا ٱلۡعَلَقَةَ مُضۡغَةࣰ فَخَلَقۡنَا ٱلۡمُضۡغَةَ عِظَٰمࣰ ا فَكَسَوۡنَا ٱلۡعِظَٰمَ لَحۡمࣰ ا ثُمَّ أَنشَأۡنَٰهُ خَلۡقًا ءَاخَرَۚ فَتَبَارَكَ ٱللَّهُ أَحۡسَنُ ٱلۡخَٰلِقِينَ','پھر نطفے کا لوتھڑا بنایا۔ پھر لوتھڑے کی بوٹی بنائی پھر بوٹی کی ہڈیاں بنائیں پھر ہڈیوں پر گوشت (پوست) چڑھایا۔ پھر اس کو نئی صورت میں بنا دیا۔ تو خدا جو سب سے بہتر بنانے والا بڑا بابرکت ہے','then We developed the drop into a clinging clot ˹of blood˺, then developed the clot into a lump ˹of flesh˺, then developed the lump into bones, then clothed the bones with flesh, then We brought it into being as a new creation. So Blessed is Allah, the Best of Creators','फिर हम ही ने नुतफ़े को जमा हुआ ख़ून बनाया फिर हम ही ने मुनजमिद खून को गोश्त का लोथड़ा बनाया हम ही ने लोथडे क़ी हड्डियाँ बनायीं फिर हम ही ने हड्डियों पर गोश्त चढ़ाया फिर हम ही ने उसको (रुह डालकर) एक दूसरी सूरत में पैदा किया तो (सुबहान अल्लाह) ख़ुदा बा बरकत है जो सब बनाने वालो से बेहतर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,15,'Al-Muminoon','ثُمَّ إِنَّكُم بَعۡدَ ذَٰلِكَ لَمَيِّتُونَ','پھر اس کے بعد تم مرجاتے ہو','After that you will surely die','फिर इसके बाद यक़ीनन तुम सब लोगों को (एक न एक दिन) मरना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,16,'Al-Muminoon','ثُمَّ إِنَّكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ تُبۡعَثُونَ','پھر قیامت کے روز اُٹھا کھڑے کئے جاؤ گے','then on the Day of Judgment you will be resurrected','इसके बाद कयामत के दिन तुम सब के सब कब्रों से उठाए जाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,17,'Al-Muminoon','وَلَقَدۡ خَلَقۡنَا فَوۡقَكُمۡ سَبۡعَ طَرَآئِقَ وَمَا كُنَّا عَنِ ٱلۡخَلۡقِ غَٰفِلِينَ','اور ہم نے تمہارے اوپر (کی جانب) سات آسمان پیدا کئے۔ اور ہم خلقت سے غافل نہیں ہیں','And indeed, We created above you seven levels ˹of heaven˺. We are never unmindful of ˹Our˺ creation','और हम ही ने तुम्हारे ऊपर तह ब तह आसमान बनाए और हम मख़लूक़ात से बेखबर नही है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,18,'Al-Muminoon','وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرࣲ فَأَسۡكَنَّٰهُ فِي ٱلۡأَرۡضِۖ وَإِنَّا عَلَىٰ ذَهَابِۭ بِهِۦ لَقَٰدِرُونَ','اور ہم ہی نے آسمان سے ایک اندازے کے ساتھ پانی نازل کیا۔ پھر اس کو زمین میں ٹھہرا دیا اور ہم اس کے نابود کردینے پر بھی قادر ہیں','We send down rain from the sky in perfect measure, causing it to soak into the earth. And We are surely able to take it away','और हमने आसमान से एक अन्दाजे क़े साथ पानी बरसाया फिर उसको ज़मीन में (हसब मसलेहत) ठहराए रखा और हम तो यक़ीनन उसके ग़ाएब कर देने पर भी क़ाबू रखते है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,19,'Al-Muminoon','فَأَنشَأۡنَا لَكُم بِهِۦ جَنَّٰتࣲ مِّن نَّخِيلࣲ وَأَعۡنَٰبࣲ لَّكُمۡ فِيهَا فَوَٰكِهُ كَثِيرَةࣱ وَمِنۡهَا تَأۡكُلُونَ','پھر ہم نے اس سے تمہارے لئے کھجوروں اور انگوروں کے باغ بنائے، ان میں تمہارے لئے بہت سے میوے پیدا ہوتے ہیں۔ اور ان میں سے تم کھاتے بھی ہو','With it We produce for you gardens of palm trees and grapevines, in which there are abundant fruits, and from which you may eat','फिर हमने उस पानी से तुम्हारे वास्ते खजूरों और अंगूरों के बाग़ात बनाए कि उनमें तुम्हारे वास्ते (तरह तरह के) बहुतेरे मेवे (पैदा होते) हैं उनमें से बाज़ को तुम खाते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,20,'Al-Muminoon','وَشَجَرَةࣰ تَخۡرُجُ مِن طُورِ سَيۡنَآءَ تَنۢبُتُ بِٱلدُّهۡنِ وَصِبۡغࣲ لِّلۡأٓكِلِينَ','اور وہ درخت بھی (ہم ہی نے پیدا کیا) جو طور سینا میں پیدا ہوتا ہے (یعنی زیتون کا درخت کہ) کھانے کے لئے روغن اور سالن لئے ہوئے اُگتا ہے','as well as ˹olive˺ trees which grow at Mount Sinai, providing oil and a condiment to eat','और (हम ही ने ज़ैतून का) दरख्त (पैदा किया) जो तूरे सैना (पहाड़) में (कसरत से) पैदा होता है जिससे तेल भी निकलता है और खाने वालों के लिए सालन भी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,21,'Al-Muminoon','وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةࣰۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهَا وَلَكُمۡ فِيهَا مَنَٰفِعُ كَثِيرَةࣱ وَمِنۡهَا تَأۡكُلُونَ','اور تمہارے لئے چارپایوں میں بھی عبرت (اور نشانی) ہے کہ ان کے پیٹوں میں ہے اس سے ہم تمہیں (دودھ) پلاتے ہیں اور تمہارے لئے ان میں اور بھی بہت سے فائدے ہیں اور بعض کو تم کھاتے بھی ہو','And there is certainly a lesson for you in cattle, from whose bellies We give you ˹milk˺ to drink, and in them are many other benefits for you, and from them you may eat','और उसमें भी शक नहीं कि तुम्हारे वास्ते चौपायों में भी इबरत की जगह है और (ख़ाक बला) जो कुछ उनके पेट में है उससे हम तुमको दूध पिलाते हैं और जानवरों में तो तुम्हारे और भी बहुत से फायदे हैं और उन्हीं में से बाज़ तुम खाते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,22,'Al-Muminoon','وَعَلَيۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ','اور ان پر اور کشتیوں پر تم سوار ہوتے ہو','And you are carried upon ˹some of˺ them and upon ships','और उन्हें जानवरों और कश्तियों पर चढे चढ़े फिरते भी हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,23,'Al-Muminoon','وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ','اور ہم نے نوح کو ان کی قوم کی طرف بھیجا تو انہوں نے ان سے کہا کہ اے قوم! خدا ہی کی عبادت کرو اس کے سوا تمہارا کوئی معبود نہیں، کیا تم ڈرتے نہیں','Indeed, We sent Noah to his people. He declared, “O my people! Worship Allah ˹alone˺. You have no god other than Him. Will you not then fear ˹Him˺?”','और हमने नूह को उनकी काैम के पास पैग़म्बर बनाकर भेजा तो नूह ने (उनसे) कहा ऐ मेरी क़ौम खुदा ही की इबादत करो उसके सिवा कोई तुम्हारा माबूद नहीं तो क्या तुम (उससे) डरते नहीं हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,24,'Al-Muminoon','فَقَالَ ٱلۡمَلَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا هَٰذَآ إِلَّا بَشَرࣱ مِّثۡلُكُمۡ يُرِيدُ أَن يَتَفَضَّلَ عَلَيۡكُمۡ وَلَوۡ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَٰٓئِكَةࣰ مَّا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ','تو ان کی قوم کے سردار جو کافر تھے کہنے لگے کہ یہ تو تم ہی جیسا آدمی ہے۔ تم پر بڑائی حاصل کرنی چاہتا ہے۔ اور اگر خدا چاہتا تو فرشتے اُتار دیتا۔ ہم نے اپنے اگلے باپ دادا میں تو یہ بات کبھی سنی نہیں تھی','But the disbelieving chiefs of his people said ˹to the masses˺, “This is only a human like you, who wants to be superior to you. Had Allah willed, He could have easily sent down angels ˹instead˺. We have never heard of this in ˹the history of˺ our forefathers','तो उनकी क़ौम के सरदारों ने जो काफिर थे कहा कि ये भी तो बस (आख़िर) तुम्हारे ही सा आदमी है (मगर) इसकी तमन्ना ये है कि तुम पर बुर्जुगी हासिल करे और अगर खुदा (पैग़म्बर ही न भेजना) चाहता तो फरिश्तों को नाज़िल करता हम ने तो (भाई) ऐसी बात अपने अगले बाप दादाओं में (भी होती) नहीं सुनी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,25,'Al-Muminoon','إِنۡ هُوَ إِلَّا رَجُلُۢ بِهِۦ جِنَّةࣱ فَتَرَبَّصُواْ بِهِۦ حَتَّىٰ حِينࣲ‏','اس آدمی کو تو دیوانگی (کا عارضہ) ہے تو اس کے بارے میں کچھ مدت انتظار کرو','He is simply insane, so bear with him for a while.”','हो न हों बस ये एक आदमी है जिसे जुनून हो गया है ग़रज़ तुम लोग एक (ख़ास) वक्त तक (इसके अन्जाम का) इन्तेज़ार देखो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,26,'Al-Muminoon','قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ','نوح نے کہا کہ پروردگار انہوں نے مجھے جھٹلایا ہے تو میری مدد کر','Noah prayed, “My Lord! Help me, because they have denied ˹me˺.”','नूह ने (ये बातें सुनकर) दुआ की ऐ मेरे पलने वाले मेरी मदद कर');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,27,'Al-Muminoon','فَأَوۡحَيۡنَآ إِلَيۡهِ أَنِ ٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا فَإِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ فَٱسۡلُكۡ فِيهَا مِن كُلࣲّ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ مِنۡهُمۡۖ وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ','پس ہم نے ان کی طرف وحی بھیجی کہ ہمارے سامنے اور ہمارے حکم سے ایک کشتی بناؤ۔ پھر جب ہمارا حکم آ پہنچے اور تنور (پانی سے بھر کر) جوش مارنے لگے تو سب (قسم کے حیوانات) میں جوڑا جوڑا (یعنی نر اور مادہ) دو دو کشتی میں بٹھا دو اور اپنے گھر والوں کو بھی، سو ان کے جن کی نسبت ان میں سے (ہلاک ہونے کا) حکم پہلے صادر ہوچکا ہے۔ اور ظالموں کے بارے میں ہم سے کچھ نہ کہنا، وہ ضرور ڈبو دیئے جائیں گے','So We inspired him: “Build the Ark under Our ˹watchful˺ Eyes and directions. Then when Our command comes and the oven bursts ˹with water˺, take on board a pair from every species along with your family—except those against whom the decree ˹to drown˺ has already been passed. And do not plead with Me for those who have done wrong, for they will surely be drowned.”','इस वजह से कि उन लोगों ने मुझे झुठला दिया तो हमने नूह के पास ''वही'' भेजी कि तुम हमारे सामने हमारे हुक्म के मुताबिक़ कश्ती बनाना शुरु करो फिर जब कल हमारा अज़ाब आ जाए और तन्नूर (से पानी) उबलने लगे तो तुम उसमें हर किस्म (के जानवरों में) से (नर मादा) दो दो का जोड़ा और अपने लड़के बालों को बिठा लो मगर उन में से जिसकी निस्बत (ग़रक़ होने का) पहले से हमारा हुक्म हो चुका है (उन्हें छोड़ दो) और जिन लोगों ने (हमारे हुकम से) सरकशी की है उनके बारे में मुझसे कुछ कहना (सुनना) नहीं क्योंकि ये लोग यकीनन डूबने वाले है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,28,'Al-Muminoon','فَإِذَا ٱسۡتَوَيۡتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلۡفُلۡكِ فَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي نَجَّىٰنَا مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ','اور جب تم اور تمہارے ساتھی کشتی میں بیٹھ جاؤ تو (خدا کا شکر کرنا اور) کہنا کہ سب تعریف خدا ہی کو (سزاوار) ہے۔ جس نے ہم کو نجات بخشی ظالم لوگوں سے','Then when you and those with you have settled in the Ark, say, “All praise is for Allah, Who saved us from the wrongdoing people.”','ग़रज़ जब तुम अपने हमराहियों के साथ कश्ती पर दुरुस्त बैठो तो कहो तमाम हम्दो सना की सज़ावार खुदा ही है जिसने हमको ज़ालिम लोगों से नजात दी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,29,'Al-Muminoon','وَقُل رَّبِّ أَنزِلۡنِي مُنزَلࣰ ا مُّبَارَكࣰ ا وَأَنتَ خَيۡرُ ٱلۡمُنزِلِينَ','اور (یہ بھی) دعا کرنا کہ اے پروردگار ہم کو مبارک جگہ اُتاریو اور تو سب سے بہتر اُتارنے والا ہے','And pray, “My Lord! Allow me a blessed landing, for You are the best accommodator.”','और दुआ करो कि ऐ मेरे पालने वाले तू मुझको (दरख्त के पानी की) बा बरकत जगह में उतारना और तू तो सब उतारने वालो ंसे बेहतर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,30,'Al-Muminoon','إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ وَإِن كُنَّا لَمُبۡتَلِينَ','بےشک اس (قصے) میں نشانیاں ہیں اور ہمیں تو آزمائش کرنی تھی','Surely in this are lessons. And We ˹always˺ put ˹people˺ to the test','इसमें शक नहीं कि हसमें (हमारी क़ुदरत की) बहुत सी निशानियाँ हैं और हमको तो बस उनका इम्तिहान लेना मंज़ूर था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,31,'Al-Muminoon','ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ','پھر ان کے بعد ہم نے ایک اور جماعت پیدا کی','Then We raised another generation after them','फिर हमने उनके बाद एक और क़ौम को (समूद) को पैदा किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,32,'Al-Muminoon','فَأَرۡسَلۡنَا فِيهِمۡ رَسُولࣰ ا مِّنۡهُمۡ أَنِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ','اور ان ہی میں سے ان میں ایک پیغمبر بھیجا (جس نے ان سے کہا) کہ خدا ہی کی عبادت کرو (کہ) اس کے سوا تمہارا کوئی معبود نہیں، تو کیا تم ڈرتے نہیں','and sent to them a messenger from among themselves, ˹declaring,˺ “Worship Allah ˹alone˺. You have no god other than Him. Will you not then fear ˹Him˺?”','और हमने उनही में से (एक आदमी सालेह को) रसूल बनाकर उन लोगों में भेजा (और उन्होंने अपनी क़ौम से कहा) कि खुदा की इबादत करो उसके सिवा कोई तुम्हारा माबूद नहीं तो क्या तुम (उससे डरते नही हो)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,33,'Al-Muminoon','وَقَالَ ٱلۡمَلَأُ مِن قَوۡمِهِ ٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِلِقَآءِ ٱلۡأٓخِرَةِ وَأَتۡرَفۡنَٰهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا مَا هَٰذَآ إِلَّا بَشَرࣱ مِّثۡلُكُمۡ يَأۡكُلُ مِمَّا تَأۡكُلُونَ مِنۡهُ وَيَشۡرَبُ مِمَّا تَشۡرَبُونَ','تو ان کی قوم کے سردار جو کافر تھے اور آخرت کے آنے کو جھوٹ سمجھتے تھے اور دنیا کی زندگی میں ہم نے ان کو آسودگی دے رکھی تھی۔ کہنے لگے کہ یہ تو تم ہی جیسا آدمی ہے، جس قسم کا کھانا تم کھاتے ہو، اسی طرح کا یہ بھی کھاتا ہے اور جو پانی تم پیتے ہو اسی قسم کا یہ بھی پیتا ہے','But the chiefs of his people—who disbelieved, denied the meeting ˹with Allah˺ in the Hereafter, and were spoiled by the worldly luxuries We had provided for them—said ˹to the masses˺, “This is only a human like you. He eats what you eat, and drinks what you drink','और उनकी क़ौम के चन्द सरदारों ने जो काफिर थे और (रोज़) आख़िरत की हाज़िरी को भी झुठलाते थे और दुनिया की (चन्द रोज़ा) ज़िन्दगी में हमने उन्हें शहवत भी दे रखी थी आपस में कहने लगे (अरे) ये तो बस तुम्हारा ही सा आदमी है जो चीज़े तुम खाते वही ये भी खाता है और जो चीज़े तुम पीते हो उन्हीं में से ये भी पीता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,34,'Al-Muminoon','وَلَئِنۡ أَطَعۡتُم بَشَرࣰ ا مِّثۡلَكُمۡ إِنَّكُمۡ إِذࣰ ا لَّخَٰسِرُونَ','اور اگر تم اپنے ہی جیسے آدمی کا کہا مان لیا تو گھاٹے میں پڑ گئے','And if you ˹ever˺ obey a human like yourselves, then you would certainly be losers','और अगर कहीं तुम लोगों ने अपने ही से आदमी की इताअत कर ली तो तुम ज़रुर घाटे में रहोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,35,'Al-Muminoon','أَيَعِدُكُمۡ أَنَّكُمۡ إِذَا مِتُّمۡ وَكُنتُمۡ تُرَابࣰ ا وَعِظَٰمًا أَنَّكُم مُّخۡرَجُونَ','کیا یہ تم سے یہ کہتا ہے کہ جب تم مر جاؤ گے اور مٹی ہو جاؤ گے اور استخوان (کے سوا کچھ نہ رہے گا) تو تم (زمین سے) نکالے جاؤ گے','Does he promise you that once you are dead and reduced to dust and bones, you will be brought forth ˹alive˺','क्या ये शख्स तुमसे वायदा करता है कि जब तुम मर जाओगे और (मर कर) सिर्फ मिट्टी और हड्डियाँ (बनकर) रह जाओगे तो तुम दुबारा ज़िन्दा करके कब्रों से निकाले जाओगे (है है अरे) जिसका तुमसे वायदा किया जाता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,36,'Al-Muminoon','۞هَيۡهَاتَ هَيۡهَاتَ لِمَا تُوعَدُونَ','جس بات کا تم سے وعدہ کیا جاتا ہے (بہت) بعید اور (بہت) بعید ہے','Impossible, simply impossible is what you are promised','बिल्कुल (अक्ल से) दूर और क़यास से बईद है (दो बार ज़िन्दा होना कैसा) बस यही तुम्हारी दुनिया की ज़िन्दगी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,37,'Al-Muminoon','إِنۡ هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا نَمُوتُ وَنَحۡيَا وَمَا نَحۡنُ بِمَبۡعُوثِينَ','زندگی تو یہی ہماری دنیا کی زندگی ہے کہ (اسی میں) ہم مرتے اور جیتے ہیں، اور ہم پھر نہیں اُٹھائے جائیں گے','There is nothing beyond our worldly life. We die, others are born, and none will be resurrected','कि हम मरते भी हैं और जीते भी हैं और हम तो फिर (दुबारा) उठाए नहीं जाएँगे हो न हो ये (सालेह) वह शख्स है जिसने खुदा पर झूठ मूठ बोहतान बाँधा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,38,'Al-Muminoon','إِنۡ هُوَ إِلَّا رَجُلٌ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبࣰ ا وَمَا نَحۡنُ لَهُۥ بِمُؤۡمِنِينَ','یہ تو ایک ایسا آدمی ہے جس نے خدا پر جھوٹ افتراء کیا ہے اور ہم اس کو ماننے والے نہیں','He is no more than a man who has fabricated a lie about Allah, and we will never believe in him.”','और हम तो कभी उस पर ईमान लाने वाले नहीं (ये हालत देखकर) सालेह ने दुआ की ऐ मेरे पालने वाले चूँकि इन लोगों ने मुझे झुठला दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,39,'Al-Muminoon','قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ','پیغمبر نے کہا کہ اے پروردگار انہوں نے مجھے جھوٹا سمجھا ہے تو میری مدد کر','The messenger prayed, “My Lord! Help me, because they have denied ˹me˺.”','तू मेरी मदद कर ख़ुदा ने फरमाया (एक ज़रा ठहर जाओ)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,40,'Al-Muminoon','قَالَ عَمَّا قَلِيلࣲ لَّيُصۡبِحُنَّ نَٰدِمِينَ','فرمایا کہ یہ تھوڑے ہی عرصے میں پشیمان ہو کر رہ جائیں گے','Allah responded, “Soon they will be truly regretful.”','अनक़रीब ही ये लोग नादिम व परेशान हो जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,41,'Al-Muminoon','فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ بِٱلۡحَقِّ فَجَعَلۡنَٰهُمۡ غُثَآءࣰۚ فَبُعۡدࣰ ا لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ','تو ان کو (وعدہٴ برحق کے مطابق) زور کی آواز نے آپکڑا، تو ہم نے ان کو کوڑا کرڈالا۔ پس ظالم لوگوں پر لعنت ہے','Then the ˹mighty˺ blast overtook them with justice, and We reduced them to rubble. So away with the wrongdoing people','ग़रज़ उन्हें यक़ीनन एक सख्त चिंघाड़ ने ले डाला तो हमने उन्हें कूडे क़रकट (का ढेर) बना छोड़ा पस ज़ालिमों पर (खुदा की) लानत है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,42,'Al-Muminoon','ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قُرُونًا ءَاخَرِينَ','پھر ان کے بعد ہم نے اور جماعتیں پیدا کیں','Then We raised other generations after them','फिर हमने उनके बाद दूसरी क़ौमों को पैदा किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,43,'Al-Muminoon','مَا تَسۡبِقُ مِنۡ أُمَّةٍ أَجَلَهَا وَمَا يَسۡتَـٔۡخِرُونَ','کوئی جماعت اپنے وقت سے نہ آگے جاسکتی ہے نہ پیچھے رہ سکتی ہے','No people can advance their doom, nor can they delay it','कोई उम्मत अपने वक्त मुर्करर से न आगे बढ़ सकती है न (उससे) पीछे हट सकती है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,44,'Al-Muminoon','ثُمَّ أَرۡسَلۡنَا رُسُلَنَا تَتۡرَاۖ كُلَّ مَا جَآءَ أُمَّةࣰ رَّسُولُهَا كَذَّبُوهُۖ فَأَتۡبَعۡنَا بَعۡضَهُم بَعۡضࣰ ا وَجَعَلۡنَٰهُمۡ أَحَادِيثَۚ فَبُعۡدࣰ ا لِّقَوۡمࣲ لَّا يُؤۡمِنُونَ','پھر ہم نے پے درپے اپنے پیغمبر بھیجتے رہے۔ جب کسی اُمت کے پاس اس کا پیغمبر آتا تھا تو وہ اسے جھٹلاتے تھے تو ہم بھی بعض کو بعض کے پیچھے (ہلاک کرتے اور ان پر عذاب) لاتے رہے اور ان کے افسانے بناتے رہے۔ پس جو لوگ ایمان نہیں لاتے ان پر لعنت','Then We sent Our messengers in succession: whenever a messenger came to his people, they denied him. So We destroyed them, one after the other, reducing them to ˹cautionary˺ tales. So away with the people who refuse to believe','फिर हमने लगातार बहुत से पैग़म्बर भेजे (मगर) जब जब किसी उम्मत का पैग़म्बर उन के पास आता तो ये लोग उसको झुठलाते थे तो हम थी (आगे पीछे) एक को दूसरे के बाद (हलाक) करते गए और हमने उन्हें (नेस्त व नाबूद करके) अफसाना बना दिया तो ईमान न लाने वालो पर ख़ुदा की लानत है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,45,'Al-Muminoon','ثُمَّ أَرۡسَلۡنَا مُوسَىٰ وَأَخَاهُ هَٰرُونَ بِـَٔايَٰتِنَا وَسُلۡطَٰنࣲ مُّبِينٍ','پھر ہم نے موسیٰ اور ان کے بھائی ہارون کو اپنی نشانیاں اور دلیل ظاہر دے کر بھیجا','Then We sent Moses and his brother Aaron with Our signs and compelling proof','फिर हमने मूसा और उनके भाई हारुन को अपनी निशानियों और वाज़ेए व रौशन दलील के साथ फिरऔन और उसके दरबार के उमराओ के पास रसूल बना कर भेजा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,46,'Al-Muminoon','إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمًا عَالِينَ','(یعنی) فرعون اور اس کی جماعت کی طرف، تو انہوں نے تکبر کیا اور وہ سرکش لوگ تھے','to Pharaoh and his chiefs, but they behaved arrogantly and were a tyrannical people','तो उन लोगो ने शेख़ी की और वह थे ही बड़े सरकश लोग');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,47,'Al-Muminoon','فَقَالُوٓاْ أَنُؤۡمِنُ لِبَشَرَيۡنِ مِثۡلِنَا وَقَوۡمُهُمَا لَنَا عَٰبِدُونَ','کہنے لگے کہ کیا ہم ان اپنے جیسے دو آدمیوں پر ایمان لے آئیں اور اُن کو قوم کے لوگ ہمارے خدمت گار ہیں','They argued, “Will we believe in two humans, like ourselves, whose people are slaves to us?”','आपस मे कहने लगे क्या हम अपने ही ऐसे दो आदमियों पर ईमान ले आएँ हालाँकि इन दोनों की (क़ौम की) क़ौम हमारी ख़िदमत गारी करती है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,48,'Al-Muminoon','فَكَذَّبُوهُمَا فَكَانُواْ مِنَ ٱلۡمُهۡلَكِينَ','تو اُن لوگوں نے اُن کی تکذیب کی سو (آخر) ہلاک کر دیئے گئے','So they rejected them both, and ˹so˺ were among those destroyed','गरज़ उन लोगों ने इन दोनों को झुठलाया तो आख़िर ये सब के सब हलाक कर डाले गए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,49,'Al-Muminoon','وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ لَعَلَّهُمۡ يَهۡتَدُونَ','اور ہم نے موسیٰ کو کتاب دی تھی تاکہ وہ لوگ ہدایت پائیں','And We certainly gave Moses the Scripture, so perhaps his people would be ˹rightly˺ guided','और हमने मूसा को किताब (तौरैत) इसलिए अता की थी कि ये लोग हिदायत पाएँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,50,'Al-Muminoon','وَجَعَلۡنَا ٱبۡنَ مَرۡيَمَ وَأُمَّهُۥٓ ءَايَةࣰ وَءَاوَيۡنَٰهُمَآ إِلَىٰ رَبۡوَةࣲ ذَاتِ قَرَارࣲ وَمَعِينࣲ‏','اور ہم نے مریم کے بیٹے (عیسیٰ) اور ان کی ماں کو (اپنی) نشانی بنایا تھا اور ان کو ایک اونچی جگہ پر جو رہنے کے لائق تھی اور جہاں (نتھرا ہوا) پانی جاری تھا، پناہ دی تھی','And We made the son of Mary and his mother a sign, and gave them refuge on high ground—a ˹suitable˺ place for rest with flowing water','और हमने मरियम के बेटे (ईसा) और उनकी माँ को (अपनी कुदरत की निशानी बनाया था) और उन दोनों को हमने एक ऊँची हमवार ठहरने के क़ाबिल चश्में वाली ज़मीन पर (रहने की) जगह दी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,51,'Al-Muminoon','يَٰٓأَيُّهَا ٱلرُّسُلُ كُلُواْ مِنَ ٱلطَّيِّبَٰتِ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ عَلِيمࣱ‏','اے پیغمبرو! پاکیزہ چیزیں کھاؤ اور عمل نیک کرو۔ جو عمل تم کرتے ہو میں ان سے واقف ہوں','O messengers! Eat from what is good and lawful, and act righteously. Indeed, I fully know what you do','और मेरा आम हुक्म था कि ऐ (मेरे पैग़म्बर) पाक व पाकीज़ा चीज़ें खाओ और अच्छे अच्छे काम करो (क्योंकि) तुम जो कुछ करते हो मैं उससे बख़ूबी वाक़िफ हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,52,'Al-Muminoon','وَإِنَّ هَٰذِهِۦٓ أُمَّتُكُمۡ أُمَّةࣰ وَٰحِدَةࣰ وَأَنَا۠ رَبُّكُمۡ فَٱتَّقُونِ','اور یہ تمہاری جماعت (حقیقت میں) ایک ہی جماعت ہے اور میں تمہارا پروردگار ہوں تو مجھ سے ڈرو','Surely this religion of yours is ˹only˺ one, and I am your Lord, so fear Me ˹alone˺','(लोगों ये दीन इस्लाम) तुम सबका मज़हब एक ही मज़हब है और मै तुम लोगों का परवरदिगार हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,53,'Al-Muminoon','فَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ زُبُرࣰ اۖ كُلُّ حِزۡبِۭ بِمَا لَدَيۡهِمۡ فَرِحُونَ','تو پھر آپس میں اپنے کام کو متفرق کرکے جدا جدا کردیا۔ جو چیزیں جس فرقے کے پاس ہے وہ اس سے خوش ہو رہا ہے','Yet the people have divided it into different sects, each rejoicing in what they have','तो बस मुझी से डरते रहो फिर लोगों ने अपने काम (में एख़तिलाफ करके उस) को टुकड़े टुकड़े कर डाला हर गिरो जो कुछ उसके पास है उसी में निहाल निहाल है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,54,'Al-Muminoon','فَذَرۡهُمۡ فِي غَمۡرَتِهِمۡ حَتَّىٰ حِينٍ','تو ان کو ایک مدت تک ان کی غفلت میں رہنے دو','So leave them ˹O Prophet˺ in their heedlessness for a while','तो (ऐ रसूल) तुम उन लोगों को उन की ग़फलत में एक ख़ास वक्त तक (पड़ा) छोड़ दो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,55,'Al-Muminoon','أَيَحۡسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالࣲ وَبَنِينَ','کیا یہ لوگ خیال کرتے ہیں کہ ہم جو دنیا میں ان کو مال اور بیٹوں سے مدد دیتے ہیں','Do they think, since We provide them with wealth and children','क्या ये लोग ये ख्याल करते है कि हम जो उन्हें माल और औलाद में तरक्क़ी दे रहे है तो हम उनके साथ भलाईयाँ करने में जल्दी कर रहे है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,56,'Al-Muminoon','نُسَارِعُ لَهُمۡ فِي ٱلۡخَيۡرَٰتِۚ بَل لَّا يَشۡعُرُونَ','تو (اس سے) ان کی بھلائی میں جلدی کر رہے ہیں (نہیں) بلکہ یہ سمجھتے ہی نہیں','that We hasten to ˹honour˺ them ˹with˺ all kinds of good? No! They are not aware','(ऐसा नहीं) बल्कि ये लोग समझते नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,57,'Al-Muminoon','إِنَّ ٱلَّذِينَ هُم مِّنۡ خَشۡيَةِ رَبِّهِم مُّشۡفِقُونَ','جو اپنے پروردگار کے خوف سے ڈرتے ہیں','Surely those who tremble in awe of their Lord','उसमें शक नहीं कि जो लोग अपने परवरदिगार की वहशत से लरज़ रहे है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,58,'Al-Muminoon','وَٱلَّذِينَ هُم بِـَٔايَٰتِ رَبِّهِمۡ يُؤۡمِنُونَ','اور جو اپنے پروردگار کی آیتوں پر ایمان رکھتے ہیں','and who believe in the revelations of their Lord','और जो लोग अपने परवरदिगार की (क़ुदरत की) निशानियों पर ईमान रखते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,59,'Al-Muminoon','وَٱلَّذِينَ هُم بِرَبِّهِمۡ لَا يُشۡرِكُونَ','اور جو اپنے پروردگار کے ساتھ شریک نہیں کرتے','and who associate none with their Lord','और अपने परवरदिगार का किसी को शरीक नही बनाते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,60,'Al-Muminoon','وَٱلَّذِينَ يُؤۡتُونَ مَآ ءَاتَواْ وَّقُلُوبُهُمۡ وَجِلَةٌ أَنَّهُمۡ إِلَىٰ رَبِّهِمۡ رَٰجِعُونَ','اور جو دے سکتے ہیں دیتے ہیں اور ان کے دل اس بات سے ڈرتے رہتے ہیں کہ ان کو اپنے پروردگار کی لوٹ کر جانا ہے','and who do whatever ˹good˺ they do with their hearts fearful, ˹knowing˺ that they will return to their Lord—','और जो लोग (ख़ुदा की राह में) जो कुछ बन पड़ता है देते हैं और फिर उनके दिल को इस बात का खटका लगा हुआ है कि उन्हें अपने परवरदिगार के सामने लौट कर जाना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,61,'Al-Muminoon','أُوْلَٰٓئِكَ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَهُمۡ لَهَا سَٰبِقُونَ','یہی لوگ نیکیوں میں جلدی کرے اور یہی اُن کے لئے آگے نکل جاتے ہیں','it is they who race to do good deeds, always taking the lead','(देखिये क्या होता है) यही लोग अलबत्ता नेकियों में जल्दी करते हैं और भलाई की तरफ (दूसरों से) लपक के आगे बढ़ जाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,62,'Al-Muminoon','وَلَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۚ وَلَدَيۡنَا كِتَٰبࣱ يَنطِقُ بِٱلۡحَقِّ وَهُمۡ لَا يُظۡلَمُونَ','اور ہم کسی شخص کو اس کی طاقت سے زیادہ تکلیف نہیں دیتے اور ہمارے پاس کتاب ہے جو سچ سچ کہہ دیتی ہے اور ان لوگوں پر ظلم نہیں کیا جائے گا','We never require of any soul more than what it can afford. And with Us is a record which speaks the truth. None will be wronged','और हम तो किसी शख्स को उसकी क़ूवत से बढ़के तकलीफ देते ही नहीं और हमारे पास तो (लोगों के आमाल की) किताब है जो बिल्कुल ठीक (हाल बताती है) और उन लोगों की (ज़र्रा बराबर) हक़ तलफी नहीं की जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,63,'Al-Muminoon','بَلۡ قُلُوبُهُمۡ فِي غَمۡرَةࣲ مِّنۡ هَٰذَا وَلَهُمۡ أَعۡمَٰلࣱ مِّن دُونِ ذَٰلِكَ هُمۡ لَهَا عَٰمِلُونَ','مگر ان کے دل ان (باتوں) کی طرف سے غفلت میں (پڑے ہوئے) ہیں، اور ان کے سوا اور اعمال بھی ہیں جو یہ کرتے رہتے ہیں','But the hearts of those ˹who disbelieve˺ are oblivious to ˹all of˺ this, and they have other ˹evil˺ deeds, opposite to this, in which they are engrossed','उनके दिल उसकी तरफ से ग़फलत में पडे हैं इसके अलावा उन के बहुत से आमाल हैं जिन्हें ये (बराबर किया करते है) और बाज़ नहीं आते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,64,'Al-Muminoon','حَتَّىٰٓ إِذَآ أَخَذۡنَا مُتۡرَفِيهِم بِٱلۡعَذَابِ إِذَا هُمۡ يَجۡـَٔرُونَ','یہاں تک کہ جب ہم نے ان میں سے آسودہ حال لوگوں کو پکڑ لیا تو وہ اس وقت چلاّئیں گے','But as soon as We seize their elite with torment, they start to cry for help','यहाँ तक कि जब हम उनके मालदारों को अज़ाब में गिरफ््तार करेंगे तो ये लोग वावैला करने लगेंगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,65,'Al-Muminoon','لَا تَجۡـَٔرُواْ ٱلۡيَوۡمَۖ إِنَّكُم مِّنَّا لَا تُنصَرُونَ','آج مت چلاّؤ! تم کو ہم سے کچھ مدد نہیں ملے گی','˹They will be told,˺ “Do not cry for help today. Surely you will never be saved from Us','(उस वक्त क़हा जाएगा) आज वावैला मत करों तुमको अब हमारी तरफ से मदद नहीं मिल सकती');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,66,'Al-Muminoon','قَدۡ كَانَتۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ تَنكِصُونَ','میری آیتیں تم کو پڑھ پڑھ کر سنائی جاتی تھیں اور تم الٹے پاؤں پھر پھر جاتے تھے','Indeed, My revelations were recited to you, but you used to back away ˹in disgust˺','(जब) हमारी आयतें तुम्हारे सामने पढ़ी जाती थीं तो तुम अकड़ते किस्सा कहते बकते हुए उन से उलटे पाँव फिर जाते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,67,'Al-Muminoon','مُسۡتَكۡبِرِينَ بِهِۦ سَٰمِرࣰ ا تَهۡجُرُونَ','ان سے سرکشی کرتے، کہانیوں میں مشغول ہوتے اور بیہودہ بکواس کرتے تھے','boasting of the Sacred House, and babbling ˹nonsense about the Quran˺ by night.”','तो क्या उन लोगों ने (हमारी) बात (कुरान) पर ग़ौर नहीं किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,68,'Al-Muminoon','أَفَلَمۡ يَدَّبَّرُواْ ٱلۡقَوۡلَ أَمۡ جَآءَهُم مَّا لَمۡ يَأۡتِ ءَابَآءَهُمُ ٱلۡأَوَّلِينَ','کیا انہوں نے اس کلام میں غور نہیں کیا یا ان کے پاس کوئی ایسی چیز آئی ہے جو ان کے اگلے باپ دادا کے پاس نہیں تھی','Is it because they have never contemplated the Word ˹of Allah˺? Or ˹because˺ there has come to them something that did not come to their forefathers','उनके पास कोई ऐसी नयी चीज़ आयी जो उनके अगले बाप दादाओं के पास नहीं आयी थी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,69,'Al-Muminoon','أَمۡ لَمۡ يَعۡرِفُواْ رَسُولَهُمۡ فَهُمۡ لَهُۥ مُنكِرُونَ','یا یہ اپنے پیغمبر کو جانتے پہنچانتے نہیں، اس وجہ سے ان کو نہیں مانتے','Or ˹because˺ they failed to recognize their Messenger, and so they denied him','या उन लोगों ने अपने रसूल ही को नहीं पहचाना तो इस वजह से इन्कार कर बैठे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,70,'Al-Muminoon','أَمۡ يَقُولُونَ بِهِۦ جِنَّةُۢۚ بَلۡ جَآءَهُم بِٱلۡحَقِّ وَأَكۡثَرُهُمۡ لِلۡحَقِّ كَٰرِهُونَ','کیا یہ کہتے ہیں کہ اسے سودا ہے (نہیں) بلکہ وہ ان کے پاس حق کو لے کر آئے ہیں اور ان میں سے اکثر حق کو ناپسند کرتے ہیں','Or ˹because˺ they say, “He is insane?” In fact, he has come to them with the truth, but most of them are resentful of the truth','या कहते हैं कि इसको जुनून हो गया है (हरगिज़ उसे जुनून नहीं) बल्कि वह तो उनके पास हक़ बात लेकर आया है और उनमें के अक्सर हक़ बात से नफरत रखते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,71,'Al-Muminoon','وَلَوِ ٱتَّبَعَ ٱلۡحَقُّ أَهۡوَآءَهُمۡ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ بَلۡ أَتَيۡنَٰهُم بِذِكۡرِهِمۡ فَهُمۡ عَن ذِكۡرِهِم مُّعۡرِضُونَ','اور خدائے (برحق) ان کی خواہشوں پر چلے تو آسمان اور زمین اور جو ان میں ہیں سب درہم برہم ہوجائیں۔ بلکہ ہم نے ان کے پاس ان کی نصیحت (کی کتاب) پہنچا دی ہے اور وہ اپنی (کتاب) نصیحت سے منہ پھیر رہے ہیں','Had the truth followed their desires, the heavens, the earth, and all those in them would have certainly been corrupted. In fact, We have brought them ˹the means to˺ their glory, but they turn away from it','और अगर कहीं हक़ उनकी नफसियानी ख्वाहिश की पैरवी करता है तो सारे आसमान व ज़मीन और जो लोग उनमें हैं (सबके सब) बरबाद हो जाते बल्कि हम तो उन्हीं के तज़किरे (जिबरील के वास्ते से) उनके पास लेकर आए तो यह लोग अपने ही तज़किरे से मुँह मोड़तें हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,72,'Al-Muminoon','أَمۡ تَسۡـَٔلُهُمۡ خَرۡجࣰ ا فَخَرَاجُ رَبِّكَ خَيۡرࣱۖ وَهُوَ خَيۡرُ ٱلرَّٰزِقِينَ','کیا تم ان سے (تبلیغ کے صلے میں) کچھ مال مانگتے ہو، تو تمہارا پروردگار کا مال بہت اچھا ہے اور وہ سب سے بہتر رزق دینے والا ہے','Or ˹is it because˺ you ˹O Prophet˺ are asking them for tribute? But the reward of your Lord is best, for He is the Best Provider','(ऐ रसूल) क्या तुम उनसे (अपनी रिसालत की) कुछ उजरत माँगतें हों तो तुम्हारे परवरदिगार की उजरत उससे कही बेहतर है और वह तो सबसे बेहतर रोज़ी देने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,73,'Al-Muminoon','وَإِنَّكَ لَتَدۡعُوهُمۡ إِلَىٰ صِرَٰطࣲ مُّسۡتَقِيمࣲ‏','اور تم تو ان کو سیدھے راستے کی طرف بلاتے ہو','And surely you are calling them to the Straight Path','और तुम तो यक़ीनन उनको सीधी राह की तरफ बुलाते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,74,'Al-Muminoon','وَإِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ عَنِ ٱلصِّرَٰطِ لَنَٰكِبُونَ','اور جو لوگ آخرت پر ایمان نہیں لاتے وہ رستے سے الگ ہو رہے ہیں','but those who disbelieve in the Hereafter are certainly deviating from that Path','और इसमें शक नहीं कि जो लोग आख़िरत पर ईमान नहीं रखते वह सीधी राह से हटे हुए हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,75,'Al-Muminoon','۞وَلَوۡ رَحِمۡنَٰهُمۡ وَكَشَفۡنَا مَا بِهِم مِّن ضُرࣲّ لَّلَجُّواْ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ','اور اگر ہم ان پر رحم کریں اور جو تکلیفیں ان کو پہنچ رہی ہیں، وہ دور کردیں تو اپنی سرکشی پر اڑے رہیں (اور) بھٹکتے (پھریں)','˹Even˺ if We had mercy on them and removed their affliction, they would still persist in their transgression, wandering blindly','और अगर हम उन पर तरस खायें और जो तकलीफें उनको (कुफ्र की वजह से) पहुँच रही हैं उन को दफा कर दें तो यक़ीनन ये लोग (और भी) अपनी सरकशी पर अड़ जाए और भटकते फिरें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,76,'Al-Muminoon','وَلَقَدۡ أَخَذۡنَٰهُم بِٱلۡعَذَابِ فَمَا ٱسۡتَكَانُواْ لِرَبِّهِمۡ وَمَا يَتَضَرَّعُونَ','اور ہم نے ان کو عذاب میں پکڑا تو بھی انہوں نے خدا کے آگے عاجزی نہ کی اور وہ عاجزی کرتے ہی نہیں','And We have already seized them with torment, but they never humbled themselves to their Lord, nor did they ˹submissively˺ appeal ˹to Him˺','और हमने उनको अज़ाब में गिरफ्तार किया तो भी वे लोग न तो अपने परवरदिगार के सामने झुके और गिड़गिड़ाएँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,77,'Al-Muminoon','حَتَّىٰٓ إِذَا فَتَحۡنَا عَلَيۡهِم بَابࣰ ا ذَا عَذَابࣲ شَدِيدٍ إِذَا هُمۡ فِيهِ مُبۡلِسُونَ','یہاں تک کہ جب ہم نے پر عذاب شدید کا دروازہ کھول دیا تو اس وقت وہاں ناامید ہوگئے','But as soon as We open for them a gate of severe punishment, they will be utterly desperate','यहाँ तक कि जब हमने उनके सामने एक सख्त अज़ाब का दरवाज़ा खोल दिया तो उस वक्त फ़ौरन ये लोग बेआस होकर बैठ रहे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,78,'Al-Muminoon','وَهُوَ ٱلَّذِيٓ أَنشَأَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلࣰ ا مَّا تَشۡكُرُونَ','اور وہی تو ہے جس نے تمہارے کان اور آنکھیں اور دل بنائے۔ (لیکن) تم کم شکرگزاری کرتے ہو','He is the One Who created for you hearing, sight, and intellect. ˹Yet˺ you hardly give any thanks','हालाँकि वही वह (मेहरबान खुदा) है जिसने तुम्हारे लिए कान और ऑंखें और दिल पैदा किये (मगर) तुम लोग हो ही बहुत कम शुक्र करने वाले');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,79,'Al-Muminoon','وَهُوَ ٱلَّذِي ذَرَأَكُمۡ فِي ٱلۡأَرۡضِ وَإِلَيۡهِ تُحۡشَرُونَ','اور وہی تو ہے جس نے تم کو زمین میں پیدا کیا اور اسی کی طرف تم جمع ہو کر جاؤ گے','And He is the One Who has dispersed you ˹all˺ over the earth, and to Him you will ˹all˺ be gathered','और वह वही (ख़ुदा) है जिसने तुम को रुए ज़मीन में (हर तरफ) फैला दिया और फिर (एक दिन) सब के सब उसी के सामने इकट्ठे किये जाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,80,'Al-Muminoon','وَهُوَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُ وَلَهُ ٱخۡتِلَٰفُ ٱلَّيۡلِ وَٱلنَّهَارِۚ أَفَلَا تَعۡقِلُونَ','اور وہی ہے جو زندگی بخشتا ہے اور موت دیتا ہے اور رات اور دن کا بدلتے رہنا اسی کا تصرف ہے، کیا تم سمجھتے نہیں','And He is the One Who gives life and causes death, and to Him belongs the alternation of the day and night. Will you not then understand','और वही वह (ख़ुदा) है जो जिलाता और मारता है कि और रात दिन का फेर बदल भी उसी के एख्तियार में है तो क्या तुम (इतना भी) नहीं समझते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,81,'Al-Muminoon','بَلۡ قَالُواْ مِثۡلَ مَا قَالَ ٱلۡأَوَّلُونَ','بات یہ ہے کہ جو بات اگلے (کافر) کہتے تھے اسی طرح کی (بات یہ) کہتے ہیں','But they ˹just˺ say what their predecessors said','(इन बातों को समझें ख़ाक नहीं) बल्कि जो अगले लोग कहते आए वैसी ही बात ये भी कहने लगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,82,'Al-Muminoon','قَالُوٓاْ أَءِذَا مِتۡنَا وَكُنَّا تُرَابࣰ ا وَعِظَٰمًا أَءِنَّا لَمَبۡعُوثُونَ','کہتے ہیں کہ جب ہم مر جائیں گے اور مٹی ہو جائیں گے اور استخوان (بوسیدہ کے سوا کچھ) نہ رہے گا تو کیا ہم پھر اٹھائے جائیں گے؟','They said, “Once we are dead and reduced to dust and bones, will we really be resurrected','कि जब हम मर जाएँगें और (मरकर) मिट्टी (का ढ़ेर) और हड्डियाँ हो जाएँगें तो क्या हम फिर दोबारा (क्रबों से ज़िन्दा करके) निकाले जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,83,'Al-Muminoon','لَقَدۡ وُعِدۡنَا نَحۡنُ وَءَابَآؤُنَا هَٰذَا مِن قَبۡلُ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ','یہ وعدہ ہم سے اور ہم سے پہلے ہمارے باپ دادا سے بھی ہوتا چلا آیا ہے (اجی) یہ تو صرف اگلے لوگوں کی کہانیاں ہیں','We have already been promised this, as well as our forefathers earlier. This is nothing but ancient fables!”','इसका वायदा तो हमसे और हमसे पहले हमारे बाप दादाओं से भी (बार हा) किया जा चुका है ये तो बस सिर्फ अगले लोगों के ढकोसले हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,84,'Al-Muminoon','قُل لِّمَنِ ٱلۡأَرۡضُ وَمَن فِيهَآ إِن كُنتُمۡ تَعۡلَمُونَ','کہو کہ اگر تم جانتے ہو تو بتاؤ کہ زمین اور جو کچھ زمین میں ہے سب کس کا مال ہے؟','Ask ˹them, O Prophet˺, “To whom belong the earth and all those on it, if you ˹really˺ know?”','(ऐ रसूल) तुम कह दो कि भला अगर तुम लोग कुछ जानते हो (तो बताओ) ये ज़मीन और जो लोग इसमें हैं किस के हैं वह फौरन जवाब देगें ख़ुदा के');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,85,'Al-Muminoon','سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَذَكَّرُونَ','جھٹ بول اٹھیں گے کہ خدا کا۔ کہو کہ پھر تم سوچتے کیوں نہیں؟','They will reply, “To Allah!” Say, “Why are you not then mindful?”','तुम कह दो कि तो क्या तुम अब भी ग़ौर न करोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,86,'Al-Muminoon','قُلۡ مَن رَّبُّ ٱلسَّمَٰوَٰتِ ٱلسَّبۡعِ وَرَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ','(ان سے) پوچھو کہ سات آسمانوں کا کون مالک ہے اور عرش عظیم کا (کون) مالک (ہے؟)','˹And˺ ask ˹them˺, “Who is the Lord of the seven heavens and the Lord of the Mighty Throne?”','(ऐ रसूल) तुम उनसे पूछो तो कि सातों आसमानों का मालिक और (इतने) बड़े अर्श का मालिक कौन है तो फौरन जवाब देगें कि (सब कुछ) खुदा ही का है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,87,'Al-Muminoon','سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَتَّقُونَ','بےساختہ کہہ دیں گے کہ یہ (چیزیں) خدا ہی کی ہیں، کہو کہ پھر تم ڈرتے کیوں نہیں؟','They will reply, “Allah.” Say, “Will you not then fear ˹Him˺?”','अब तुम कहो तो क्या तुम अब भी (उससे) नहीं डरोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,88,'Al-Muminoon','قُلۡ مَنۢ بِيَدِهِۦ مَلَكُوتُ كُلِّ شَيۡءࣲ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيۡهِ إِن كُنتُمۡ تَعۡلَمُونَ','کہو کہ اگر تم جانتے ہو تو بتاؤ کہ وہ کون ہے جس کے ہاتھ میں ہر چیز کی بادشاہی ہے اور وہ پناہ دیتا ہے اور اس کے مقابل کوئی کسی کو پناہ نہیں دے سکتا','Ask ˹them also,˺ “In Whose Hands is the authority over all things, protecting ˹all˺ while none can protect against Him, if you ˹really˺ know?”','(ऐ रसूल) तुम उनसे पूछो कि भला अगर तुम कुछ जानते हो (तो बताओ) कि वह कौन शख्स है- जिसके एख्तेयार में हर चीज़ की बादशाहत है वह (जिसे चाहता है) पनाह देता है और उस (के अज़ाब) से पनाह नहीं दी जा सकती');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,89,'Al-Muminoon','سَيَقُولُونَ لِلَّهِۚ قُلۡ فَأَنَّىٰ تُسۡحَرُونَ','فوراً کہہ دیں گے کہ (ایسی بادشاہی تو) خدا ہی کی ہے، تو کہو پھر تم پر جادو کہاں سے پڑ جاتا ہے؟','They will reply, “Allah.” Say, “How are you then so deluded?”','तो ये लोग फौरन बोल उठेंगे कि (सब एख्तेयार) ख़ुदा ही को है- अब तुम कह दो कि तुम पर जादू कहाँ किया जाता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,90,'Al-Muminoon','بَلۡ أَتَيۡنَٰهُم بِٱلۡحَقِّ وَإِنَّهُمۡ لَكَٰذِبُونَ','بات یہ ہے کہ ہم نے ان کے پاس حق پہنچا دیا ہے اور جو (بت پرستی کئے جاتے ہیں) بےشک جھوٹے ہیں','In fact, We have brought them the truth, and they are certainly liars','बात ये है कि हमने उनके पास हक़ बात पहुँचा दी और ये लोग यक़ीनन झूठे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,91,'Al-Muminoon','مَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدࣲ وَمَا كَانَ مَعَهُۥ مِنۡ إِلَٰهٍۚ إِذࣰ ا لَّذَهَبَ كُلُّ إِلَٰهِۭ بِمَا خَلَقَ وَلَعَلَا بَعۡضُهُمۡ عَلَىٰ بَعۡضࣲۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ','خدا نے نہ تو (اپنا) کسی کو بیٹا بنایا ہے اور نہ اس کے ساتھ کوئی معبود ہے، ایسا ہوتا تو ہر معبود اپنی اپنی مخلوقات کو لے کر چل دیتا اور ایک دوسرے پر غالب آجاتا۔ یہ لوگ جو کچھ خدا کے بارے میں بیان کرتے ہیں خدا اس سے پاک ہے','Allah has never had ˹any˺ offspring, nor is there any god besides Him. Otherwise, each god would have taken away what he created, and they would have tried to dominate one another. Glorified is Allah above what they claim','न तो अल्लाह ने किसी को (अपना) बेटा बनाया है और न उसके साथ कोई और ख़ुदा है (अगर ऐसा होता) उस वक्त हर खुदा अपने अपने मख़लूक़ को लिए लिए फिरता और यक़ीनन एक दूसरे पर चढ़ाई करता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,92,'Al-Muminoon','عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ','وہ پوشیدہ اور ظاہر کو جانتا ہے اور (مشرک) جو اس کے ساتھ شریک کرتے ہیں اس کی شان اس سے اونچی ہے','˹He is the˺ Knower of the seen and unseen. Exalted is He above what they associate ˹with Him˺','(और ख़ूब जंग होती) जो जो बाते ये लोग (ख़ुदा की निस्बत) बयान करते हैं उस से ख़ुदा पाक व पाकीज़ा है वह पोशीदा और हाज़िर (सबसे) खुदा वाक़िफ है ग़रज़ वह उनके शिर्क से (बिल्कुल पाक और) बालातर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,93,'Al-Muminoon','قُل رَّبِّ إِمَّا تُرِيَنِّي مَا يُوعَدُونَ','(اے محمدﷺ) کہو کہ اے پروردگار جس عذاب کا ان (کفار) سے وعدہ ہو رہا ہے، اگر تو میری زندگی میں ان پر نازل کرکے مجھے بھی دکھادے','Say, ˹O Prophet,˺ “My Lord! Should You show me what they are threatened with','(ऐ रसूल) तुम दुआ करो कि ऐ मेरे पालने वाले जिस (अज़ाब) का तूने उनसे वायदा किया है अगर शायद तू मुझे दिखाए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,94,'Al-Muminoon','رَبِّ فَلَا تَجۡعَلۡنِي فِي ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ','تو اے پروردگار مجھے (اس سے محفوظ رکھیئے اور) ان ظالموں میں شامل نہ کیجیئے','then, my Lord, do not count me among the wrongdoing people.”','तो परवरदिगार मुझे उन ज़ालिम लोगों के हमराह न करना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,95,'Al-Muminoon','وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمۡ لَقَٰدِرُونَ','اور جو وعدہ ہم ان سے کر رہے ہیں ہم تم کو دکھا کر ان پر نازل کرنے پر قادر ہیں','We are indeed able to show you what We have threatened them with','और (ऐ रसूल) हम यक़ीनन इस पर क़ादिर हैं कि जिस (अज़ाब) का हम उनसे वायदा करते हैं तुम्हें दिखा दें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,96,'Al-Muminoon','ٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ ٱلسَّيِّئَةَۚ نَحۡنُ أَعۡلَمُ بِمَا يَصِفُونَ','اور بری بات کے جواب میں ایسی بات کہو جو نہایت اچھی ہو۔ اور یہ جو کچھ بیان کرتے ہیں ہمیں خوب معلوم ہے','Respond to evil with what is best. We know well what they claim','और बुरी बात के जवाब में ऐसी बात कहो जो निहायत अच्छी हो जो कुछ ये लोग (तुम्हारी निस्बत) बयान करते हैं उससे हम ख़ूब वाक़िफ हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,97,'Al-Muminoon','وَقُل رَّبِّ أَعُوذُ بِكَ مِنۡ هَمَزَٰتِ ٱلشَّيَٰطِينِ','اور کہو کہ اے پروردگار! میں شیطانوں کے وسوسوں سے تیری پناہ مانگتا ہو','And say, “My Lord! I seek refuge in You from the temptations of the devils','और (ये भी) दुआ करो कि ऐ मेरे पालने वाले मै शैतान के वसवसों से तेरी पनाह माँगता हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,98,'Al-Muminoon','وَأَعُوذُ بِكَ رَبِّ أَن يَحۡضُرُونِ','اور اے پروردگار! اس سے بھی تیری پناہ مانگتا ہوں کہ وہ میرے پاس آموجود ہوں','And I seek refuge in You, my Lord, that they ˹even˺ come near me.”','और ऐ मेरे परवरदिगार इससे भी तेरी पनाह माँगता हूँ कि शयातीन मेरे पास आएँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,99,'Al-Muminoon','حَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ رَبِّ ٱرۡجِعُونِ','(یہ لوگ اسی طرح غفلت میں رہیں گے) یہاں تک کہ جب ان میں سے کسی کے پاس موت آجائے گی تو کہے گا کہ اے پروردگار! مجھے پھر (دنیا میں) واپس بھیج دے','When death approaches any of them, they cry, “My Lord! Let me go back','(और कुफ्फ़ार तो मानेगें नहीं) यहाँ तक कि जब उनमें से किसी को मौत आयी तो कहने लगे परवरदिगार तू मुझे (एक बार) उस मुक़ाम (दुनिया) में छोड़ आया हूँ फिर वापस कर दे ताकि मै (अपकी दफ़ा) अच्छे अच्छे काम करूं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,100,'Al-Muminoon','لَعَلِّيٓ أَعۡمَلُ صَٰلِحࣰ ا فِيمَا تَرَكۡتُۚ كَلَّآۚ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَاۖ وَمِن وَرَآئِهِم بَرۡزَخٌ إِلَىٰ يَوۡمِ يُبۡعَثُونَ','تاکہ میں اس میں جسے چھوڑ آیا ہوں نیک کام کیا کروں۔ ہرگز نہیں۔ یہ ایک ایسی بات ہے کہ وہ اسے زبان سے کہہ رہا ہوگا (اور اس کے ساتھ عمل نہیں ہوگا) اور اس کے پیچھے برزخ ہے (جہاں وہ) اس دن تک کہ (دوبارہ) اٹھائے جائیں گے، (رہیں گے)','so I may do good in what I left behind.” Never! It is only a ˹useless˺ appeal they make. And there is a barrier behind them until the Day they are resurrected','(जवाब दिया जाएगा) हरगिज़ नहीं ये एक लग़ो बात है- जिसे वह बक रहा और उनके (मरने के) बाद (आलमे) बरज़ख़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,101,'Al-Muminoon','فَإِذَا نُفِخَ فِي ٱلصُّورِ فَلَآ أَنسَابَ بَيۡنَهُمۡ يَوۡمَئِذࣲ وَلَا يَتَسَآءَلُونَ','پھر جب صور پھونکا جائے گا تو نہ تو ان میں قرابتیں ہوں گی اور نہ ایک دوسرے کو پوچھیں گے','Then, when the Trumpet will be blown, there will be no kinship between them on that Day, nor will they ˹even care to˺ ask about one another','(जहाँ) क़ब्रों से उठाए जाएँगें (रहना होगा) फिर जिस वक्त सूर फूँका जाएगा तो उस दिन न लोगों में क़राबत दारियाँ रहेगी और न एक दूसरे की बात पूछेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,102,'Al-Muminoon','فَمَن ثَقُلَتۡ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ','تو جن کے (عملوں کے) بوجھ بھاری ہوں گے۔ وہ فلاح پانے والے ہیں','As for those whose scale is heavy ˹with good deeds˺, it is they who will be successful','फिर जिन (के नेकियों) के पल्लें भारी होगें तो यही लोग कामयाब होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,103,'Al-Muminoon','وَمَنۡ خَفَّتۡ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فِي جَهَنَّمَ خَٰلِدُونَ','اور جن کے بوجھ ہلکے ہوں گے وہ لوگ ہیں جنہوں نے اپنے تئیں خسارے میں ڈالا، ہمیشہ دوزخ میں رہیں گے','But those whose scale is light, they will have doomed themselves, staying in Hell forever','और जिन (के नेकियों) के पल्लें हल्के होंगे तो यही लोग है जिन्होंने अपना नुक़सान किया कि हमेशा जहन्नुम में रहेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,104,'Al-Muminoon','تَلۡفَحُ وُجُوهَهُمُ ٱلنَّارُ وَهُمۡ فِيهَا كَٰلِحُونَ','آگ ان کے مونہوں کو جھلس دے گی اور وہ اس میں تیوری چڑھائے ہوں گے','The Fire will burn their faces, leaving them deformed','और (उनकी ये हालत होगी कि) जहन्नुम की आग उनके मुँह को झुलसा देगी और लोग मुँह बनाए हुए होगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,105,'Al-Muminoon','أَلَمۡ تَكُنۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُم بِهَا تُكَذِّبُونَ','کیا تم کو میری آیتیں پڑھ کر نہیں سنائی جاتیں تھیں (نہیں) تم ان کو سنتے تھے (اور) جھٹلاتے تھے','˹It will be said,˺ “Were My revelations not recited to you, but you used to deny them?”','(उस वक्त हम पूछेंगें) क्या तुम्हारे सामने मेरी आयतें न पढ़ी गयीं थीं (ज़रुर पढ़ी गयी थीं) तो तुम उन्हें झुठलाया करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,106,'Al-Muminoon','قَالُواْ رَبَّنَا غَلَبَتۡ عَلَيۡنَا شِقۡوَتُنَا وَكُنَّا قَوۡمࣰ ا ضَآلِّينَ','اے ہمارے پروردگار! ہم پر ہماری کم بختی غالب ہوگئی اور ہم رستے سے بھٹک گئے','They will cry, “Our Lord! Our ill-fate took hold of us, so we became a misguided people','वह जवाब देगें ऐ हमारे परवरदिगार हमको हमारी कम्बख्ती ने आज़माया और हम गुमराह लोग थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,107,'Al-Muminoon','رَبَّنَآ أَخۡرِجۡنَا مِنۡهَا فَإِنۡ عُدۡنَا فَإِنَّا ظَٰلِمُونَ','اے پروردگار! ہم کو اس میں سے نکال دے، اگر ہم پھر (ایسے کام) کریں تو ظالم ہوں گے','Our Lord! Take us out of this ˹Fire˺. Then if we ever return ˹to denial˺, we will truly be wrongdoers.”','परवरदिगार हमको (अबकी दफा) किसी तरह इस जहन्नुम से निकाल दे फिर अगर दोबारा हम ऐसा करें तो अलबत्ता हम कुसूरवार हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,108,'Al-Muminoon','قَالَ ٱخۡسَـُٔواْ فِيهَا وَلَا تُكَلِّمُونِ','(خدا) فرمائے گا کہ اسی میں ذلت کے ساتھ پڑے رہو اور مجھ سے بات نہ کرو','Allah will respond, “Be despised in there! Do not ˹ever˺ plead with Me ˹again˺','ख़ुदा फरमाएगा दूर हो इसी में (तुम को रहना होगा) और (बस) मुझ से बात न करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,109,'Al-Muminoon','إِنَّهُۥ كَانَ فَرِيقࣱ مِّنۡ عِبَادِي يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ','میرے بندوں میں ایک گروہ تھا جو دعا کیا کرتا تھا کہ اے ہمارے پروردگار ہم ایمان لائے تو تُو ہم کو بخش دے اور ہم پر رحم کر اور تو سب سے بہتر رحم کرنے والا ہے','Indeed, there was a group of My servants who used to pray, ‘Our Lord! We have believed, so forgive us and have mercy on us, for You are the best of those who show mercy,’','मेरे बन्दों में से एक गिरोह ऐसा भी था जो (बराबर) ये दुआ करता था कि ऐ हमारे पालने वाले हम ईमान लाए तो तू हमको बख्श दे और हम पर रहम कर तू तो तमाम रहम करने वालों से बेहतर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,110,'Al-Muminoon','فَٱتَّخَذۡتُمُوهُمۡ سِخۡرِيًّا حَتَّىٰٓ أَنسَوۡكُمۡ ذِكۡرِي وَكُنتُم مِّنۡهُمۡ تَضۡحَكُونَ','تو تم ان سے تمسخر کرتے رہے یہاں تک کہ ان کے پیچھے میری یاد بھی بھول گئے اور تم (ہمیشہ) ان سے ہنسی کیا کرتے تھے','but you were ˹so busy˺ making fun of them that it made you forget My remembrance. And you used to laugh at them','तो तुम लोगों ने उन्हें मसखरा बना लिया-यहाँ तक कि (गोया) उन लोगों ने तुम से मेरी याद भुला दी और तुम उन पर (बराबर) हँसते रहे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,111,'Al-Muminoon','إِنِّي جَزَيۡتُهُمُ ٱلۡيَوۡمَ بِمَا صَبَرُوٓاْ أَنَّهُمۡ هُمُ ٱلۡفَآئِزُونَ','آج میں نے اُن کو اُن کے صبر کا بدلہ دیا، کہ وہ کامیاب ہوگئے','Today I have indeed rewarded them for their perseverance: they are certainly the triumphant.”','मैने आज उनको उनके सब्र का अच्छा बदला दिया कि यही लोग अपनी (ख़ातिरख्वाह) मुराद को पहुँचने वाले हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,112,'Al-Muminoon','قَٰلَ كَمۡ لَبِثۡتُمۡ فِي ٱلۡأَرۡضِ عَدَدَ سِنِينَ','(خدا) پوچھے گا کہ تم زمین میں کتنے برس رہے؟','He will ask ˹them˺, “How many years did you remain on earth?”','(फिर उनसे) ख़ुदा पूछेगा कि (आख़िर) तुम ज़मीन पर कितने बरस रहे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,113,'Al-Muminoon','قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمࣲ فَسۡـَٔلِ ٱلۡعَآدِّينَ','وہ کہیں گے کہ ہم ایک روز یا ایک روز سے بھی کم رہے تھے، شمار کرنے والوں سے پوچھ لیجیئے','They will reply, “We remained ˹only˺ a day or part of a day. But ask those who kept count.”','वह कहेंगें (बरस कैसा) हम तो बस पूरा एक दिन रहे या एक दिन से भी कम');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,114,'Al-Muminoon','قَٰلَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلࣰ اۖ لَّوۡ أَنَّكُمۡ كُنتُمۡ تَعۡلَمُونَ','(خدا) فرمائے گا کہ (وہاں) تم (بہت ہی) کم رہے۔ کاش تم جانتے ہوتے','He will say, “You only remained for a little while, if only you knew','तो तुम शुमार करने वालों से पूछ लो ख़ुदा फरमाएगा बेशक तुम (ज़मीन में) बहुत ही कम ठहरे काश तुम (इतनी बात भी दुनिया में) समझे होते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,115,'Al-Muminoon','أَفَحَسِبۡتُمۡ أَنَّمَا خَلَقۡنَٰكُمۡ عَبَثࣰ ا وَأَنَّكُمۡ إِلَيۡنَا لَا تُرۡجَعُونَ','کیا تم یہ خیال کرتے ہو کہ ہم نے تم کو بےفائدہ پیدا کیا ہے اور یہ تم ہماری طرف لوٹ کر نہیں آؤ گے؟','Did you then think that We had created you without purpose, and that you would never be returned to Us?”','तो क्या तुम ये ख्याल करते हो कि हमने तुमको (यूँ ही) बेकार पैदा किया और ये कि तुम हमारे हुज़ूर में लौटा कर न लाए जाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,116,'Al-Muminoon','فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۖ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡكَرِيمِ','تو خدا جو سچا بادشاہ ہے (اس کی شان) اس سے اونچی ہے، اس کے سوا کوئی معبود نہیں، وہی عرش بزرگ کا مالک ہے','Exalted is Allah, the True King! There is no god ˹worthy of worship˺ except Him, the Lord of the Honourable Throne','तो ख़ुदा जो सच्चा बादशाह (हर चीज़ से) बरतर व आला है उसके सिवा कोई माबूद नहीं (वहीं) अर्श बुर्जुग़ का मालिक है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,117,'Al-Muminoon','وَمَن يَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرۡهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلۡكَٰفِرُونَ','اور جو شخص خدا کے ساتھ اور معبود کو پکارتا ہے جس کی اس کے پاس کچھ بھی سند نہیں تو اس کا حساب خدا ہی کے ہاں ہوگا۔ کچھ شک نہیں کہ کافر رستگاری نہیں پائیں گے','Whoever invokes, besides Allah, another god—for which they can have no proof—they will surely find their penalty with their Lord. Indeed, the disbelievers will never succeed','और जो शख्स ख़ुदा के साथ दूसरे माबूद की भी परसतिश करेगा उसके पास इस शिर्क की कोई दलील तो है नहीं तो बस उसका हिसाब (किताब) उसके परवरदिगार ही के पास होगा (मगर याद रहे कि कुफ्फ़ार हरगिज़ फलॉह पाने वाले नहीं)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (23,118,'Al-Muminoon','وَقُل رَّبِّ ٱغۡفِرۡ وَٱرۡحَمۡ وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ','اور خدا سے دعا کرو کہ میرے پروردگار مجھے بخش دے اور (مجھ پر) رحم کر اور تو سب سے بہتر رحم کرنے والا ہے','Say, ˹O Prophet,˺ “My Lord! Forgive and have mercy, for You are the best of those who show mercy.”','और (ऐ रसूल) तुम कह दो परवरदिगार तू (मेरी उम्मत को) बख्श दे और तरस खा और तू तो सब रहम करने वालों से बेहतर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,1,'An-Noor','سُورَةٌ أَنزَلۡنَٰهَا وَفَرَضۡنَٰهَا وَأَنزَلۡنَا فِيهَآ ءَايَٰتِۭ بَيِّنَٰتࣲ لَّعَلَّكُمۡ تَذَكَّرُونَ','یہ (ایک) سورت ہے جس کو ہم نے نازل کیا اور اس (کے احکام) کو فرض کر دیا، اور اس میں واضح المطالب آیتیں نازل کیں تاکہ تم یاد رکھو','˹This is˺ a sûrah which We have revealed and made ˹its rulings˺ obligatory, and revealed in it clear commandments so that you may be mindful','(ये) एक सूरा है जिसे हमने नाज़िल किया है और उस (के एहक़ाम) को फर्ज क़र दिया है और इसमें हमने वाज़ेए व रौशन आयतें नाज़िल की हैं ताकि तुम (ग़ौर करके) नसीहत हासिल करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,2,'An-Noor','ٱلزَّانِيَةُ وَٱلزَّانِي فَٱجۡلِدُواْ كُلَّ وَٰحِدࣲ مِّنۡهُمَا مِاْئَةَ جَلۡدَةࣲۖ وَلَا تَأۡخُذۡكُم بِهِمَا رَأۡفَةࣱ فِي دِينِ ٱللَّهِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ وَلۡيَشۡهَدۡ عَذَابَهُمَا طَآئِفَةࣱ مِّنَ ٱلۡمُؤۡمِنِينَ','بدکاری کرنے والی عورت اور بدکاری کرنے والا مرد (جب ان کی بدکاری ثابت ہوجائے تو) دونوں میں سے ہر ایک کو سو درے مارو۔ اور اگر تم خدا اور روز آخرت پر ایمان رکھتے ہو تو شرع خدا (کے حکم) میں تمہیں ان پر ہرگز ترس نہ آئے۔ اور چاہیئے کہ ان کی سزا کے وقت مسلمانوں کی ایک جماعت بھی موجود ہو','As for female and male fornicators, give each of them one hundred lashes, and do not let pity for them make you lenient in ˹enforcing˺ the law of Allah, if you ˹truly˺ believe in Allah and the Last Day. And let a number of believers witness their punishment','़ज़िना करने वाली औरत और ज़िना करने वाले मर्द इन दोनों में से हर एक को सौ (सौ) कोडे मारो और अगर तुम ख़ुदा और रोजे अाख़िरत पर ईमान रखते हो तो हुक्मे खुदा के नाफिज़ करने में तुमको उनके बारे में किसी तरह की तरस का लिहाज़ न होने पाए और उन दोनों की सज़ा के वक्त मोमिन की एक जमाअत को मौजूद रहना चाहिए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,3,'An-Noor','ٱلزَّانِي لَا يَنكِحُ إِلَّا زَانِيَةً أَوۡ مُشۡرِكَةࣰ وَٱلزَّانِيَةُ لَا يَنكِحُهَآ إِلَّا زَانٍ أَوۡ مُشۡرِكࣱۚ وَحُرِّمَ ذَٰلِكَ عَلَى ٱلۡمُؤۡمِنِينَ','بدکار مرد تو بدکار یا مشرک عورت کے سوا نکاح نہیں کرتا اور بدکار عورت کو بھی بدکار یا مشرک مرد کے سوا اور کوئی نکاح میں نہیں لاتا اور یہ (یعنی بدکار عورت سے نکاح کرنا) مومنوں پر حرام ہے','A male fornicator would only marry a female fornicator or idolatress. And a female fornicator would only be married to a fornicator or idolater. This is ˹all˺ forbidden to the believers','ज़िना करने वाला मर्द तो ज़िना करने वाली औरत या मुशरिका से निकाह करेगा और ज़िना करने वाली औरत भी बस ज़िना करने वाले ही मर्द या मुशरिक से निकाह करेगी और सच्चे ईमानदारों पर तो इस क़िस्म के ताल्लुक़ात हराम हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,4,'An-Noor','وَٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ثُمَّ لَمۡ يَأۡتُواْ بِأَرۡبَعَةِ شُهَدَآءَ فَٱجۡلِدُوهُمۡ ثَمَٰنِينَ جَلۡدَةࣰ وَلَا تَقۡبَلُواْ لَهُمۡ شَهَٰدَةً أَبَدࣰ اۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ','اور جو لوگ پرہیزگار عورتوں کو بدکاری کا عیب لگائیں اور اس پر چار گواہ نہ لائیں تو ان کو اسی درے مارو اور کبھی ان کی شہادت قبول نہ کرو۔ اور یہی بدکردار ہیں','Those who accuse chaste women ˹of adultery˺ and fail to produce four witnesses, give them eighty lashes ˹each˺. And do not ever accept any testimony from them—for they are indeed the rebellious—','और जो लोग पाक दामन औरतों पर (ज़िना की) तोहमत लगाएँ फिर (अपने दावे पर) चार गवाह पेश न करें तो उन्हें अस्सी कोड़ें मारो और फिर (आइन्दा) कभी उनकी गवाही कुबूल न करो और (याद रखो कि) ये लोग ख़ुद बदकार हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,5,'An-Noor','إِلَّا ٱلَّذِينَ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُواْ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمࣱ‏','ہاں جو اس کے بعد توبہ کرلیں اور (اپنی حالت) سنوار لیں تو خدا (بھی) بخشنے والا مہربان ہے','except those who repent afterwards and mend their ways, then surely Allah is All-Forgiving, Most Merciful','मगर हाँ जिन लोगों ने उसके बाद तौबा कर ली और अपनी इसलाह की तो बेशक ख़ुदा बड़ा बख्शने वाला मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,6,'An-Noor','وَٱلَّذِينَ يَرۡمُونَ أَزۡوَٰجَهُمۡ وَلَمۡ يَكُن لَّهُمۡ شُهَدَآءُ إِلَّآ أَنفُسُهُمۡ فَشَهَٰدَةُ أَحَدِهِمۡ أَرۡبَعُ شَهَٰدَٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ','اور جو لوگ اپنی عورتوں پر بدکاری کی تہمت لگائیں اور خود ان کے سوا ان کے گواہ نہ ہوں تو ہر ایک کی شہادت یہ ہے کہ پہلے تو چار بار خدا کی قسم کھائے کہ بےشک وہ سچا ہے','And those who accuse their wives ˹of adultery˺ but have no witness except themselves, the accuser must testify, swearing four times by Allah that he is telling the truth','और जो लोग अपनी बीवियों पर (ज़िना) का ऐब लगाएँ और (इसके सुबूत में) अपने सिवा उनका कोई गवाह न हो तो ऐसे लोगों में से एक की गवाही चार मरतबा इस तरह होगी कि वह (हर मरतबा) ख़ुदा की क़सम खाकर बयान करे कि वह (अपने दावे में) जरुर सच्चा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,7,'An-Noor','وَٱلۡخَٰمِسَةُ أَنَّ لَعۡنَتَ ٱللَّهِ عَلَيۡهِ إِن كَانَ مِنَ ٱلۡكَٰذِبِينَ','اور پانچویں بار یہ (کہے) کہ اگر وہ جھوٹا ہو تو اس پر خدا کی لعنت','and a fifth oath that Allah may condemn him if he is lying','और पाँचवी (मरतबा) यूँ (कहेगा) अगर वह झूट बोलता हो तो उस पर ख़ुदा की लानत');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,8,'An-Noor','وَيَدۡرَؤُاْ عَنۡهَا ٱلۡعَذَابَ أَن تَشۡهَدَ أَرۡبَعَ شَهَٰدَٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلۡكَٰذِبِينَ','اور عورت سے سزا کو یہ بات ٹال سکتی ہے کہ وہ پہلے چار بار خدا کی قسم کھائے کہ بےشک یہ جھوٹا ہے','For her to be spared the punishment, she must swear four times by Allah that he is telling a lie','और औरत (के सर से) इस तरह सज़ा टल सकती है कि वह चार मरतबा ख़ुदा की क़सम खा कर बयान कर दे कि ये शख्स (उसका शौहर अपने दावे में) ज़रुर झूठा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,9,'An-Noor','وَٱلۡخَٰمِسَةَ أَنَّ غَضَبَ ٱللَّهِ عَلَيۡهَآ إِن كَانَ مِنَ ٱلصَّٰدِقِينَ','اور پانچویں دفعہ یوں (کہے) کہ اگر یہ سچا ہو تو مجھ پر خدا کا غضب (نازل ہو)','and a fifth oath that Allah may be displeased with her if he is telling the truth','और पाँचवी मरतबा यूँ करेगी कि अगर ये शख्स (अपने दावे में) सच्चा हो तो मुझ पर खुदा का ग़ज़ब पड़े');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,10,'An-Noor','وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ وَأَنَّ ٱللَّهَ تَوَّابٌ حَكِيمٌ','اور اگر تم پر خدا کا فضل اور اس کی مہربانی نہ ہوتی تو بہت سی خرابیاں پیدا ہوجاتیں۔ مگر وہ صاحب کرم ہے اور یہ کہ خدا توبہ قبول کرنے والا حکیم ہے','˹You would have suffered,˺ had it not been for Allah’s grace and mercy upon you, and had Allah not been Accepting of Repentance, All-Wise','और अगर तुम पर ख़ुदा का फज़ल (व करम) और उसकी मेहरबानी न होती तो देखते कि तोहमत लगाने वालों का क्या हाल होता और इसमें शक ही नहीं कि ख़ुदा बड़ा तौबा क़ुबूल करने वाला हकीम है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,11,'An-Noor','إِنَّ ٱلَّذِينَ جَآءُو بِٱلۡإِفۡكِ عُصۡبَةࣱ مِّنكُمۡۚ لَا تَحۡسَبُوهُ شَرࣰّ ا لَّكُمۖ بَلۡ هُوَ خَيۡرࣱ لَّكُمۡۚ لِكُلِّ ٱمۡرِيࣲٕ مِّنۡهُم مَّا ٱكۡتَسَبَ مِنَ ٱلۡإِثۡمِۚ وَٱلَّذِي تَوَلَّىٰ كِبۡرَهُۥ مِنۡهُمۡ لَهُۥ عَذَابٌ عَظِيمࣱ‏','جن لوگوں نے بہتان باندھا ہے تم ہی میں سے ایک جماعت ہے اس کو اپنے حق میں برا نہ سمجھنا۔ بلکہ وہ تمہارے لئے اچھا ہے۔ ان میں سے جس شخص نے گناہ کا جتنا حصہ لیا اس کے لئے اتنا ہی وبال ہے۔ اور جس نے ان میں سے اس بہتان کا بڑا بوجھ اٹھایا ہے اس کو بڑا عذاب ہوگا','Indeed, those who came up with that ˹outrageous˺ slander are a group of you. Do not think this is bad for you. Rather, it is good for you. They will be punished, each according to their share of the sin. As for their mastermind, he will suffer a tremendous punishment','बेशक जिन लोगों ने झूठी तोहमत लगायी वह तुम्ही में से एक गिरोह है तुम अपने हक़ में इस तोहमत को बड़ा न समझो बल्कि ये तुम्हारे हक़ में बेहतर है इनमें से जिस शख्स ने जितना गुनाह समेटा वह उस (की सज़ा) को खुद भुगतेगा और उनमें से जिस शख्स ने तोहमत का बड़ा हिस्सा लिया उसके लिए बड़ी (सख्त) सज़ा होगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,12,'An-Noor','لَّوۡلَآ إِذۡ سَمِعۡتُمُوهُ ظَنَّ ٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بِأَنفُسِهِمۡ خَيۡرࣰ ا وَقَالُواْ هَٰذَآ إِفۡكࣱ مُّبِينࣱ‏','جب تم نے وہ بات سنی تھی تو مومن مردوں اور عورتوں نے کیوں اپنے دلوں میں نیک گمان نہ کیا۔ اور کیوں نہ کہا کہ یہ صریح طوفان ہے','If only the believing men and women had thought well of one another, when you heard this ˹rumour˺, and said, “This is clearly ˹an outrageous˺ slander!”','और जब तुम लोगो ने उसको सुना था तो उसी वक्त ईमानदार मर्दों और ईमानदार औरतों ने अपने लोगों पर भलाई का गुमान क्यो न किया और ये क्यों न बोल उठे कि ये तो खुला हुआ बोहतान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,13,'An-Noor','لَّوۡلَا جَآءُو عَلَيۡهِ بِأَرۡبَعَةِ شُهَدَآءَۚ فَإِذۡ لَمۡ يَأۡتُواْ بِٱلشُّهَدَآءِ فَأُوْلَٰٓئِكَ عِندَ ٱللَّهِ هُمُ ٱلۡكَٰذِبُونَ','یہ (افتراء پرداز) اپنی بات (کی تصدیق) کے (لئے) چار گواہ کیوں نہ لائے۔ تو جب یہ گواہ نہیں لاسکے تو خدا کے نزدیک یہی جھوٹے ہیں','Why did they not produce four witnesses? Now, since they have failed to produce witnesses, they are ˹truly˺ liars in the sight of Allah','और जिन लोगों ने तोहमत लगायी थी अपने दावे के सुबूत में चार गवाह क्यों न पेश किए फिर जब इन लोगों ने गवाह न पेश किये तो ख़ुदा के नज़दीक यही लोग झूठे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,14,'An-Noor','وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ لَمَسَّكُمۡ فِي مَآ أَفَضۡتُمۡ فِيهِ عَذَابٌ عَظِيمٌ','اور اگر دنیا اور آخرت میں تم پر خدا کا فضل اور اس کی رحمت نہ ہوتی تو جس بات کا تم چرچا کرتے تھے اس کی وجہ سے تم پر بڑا (سخت) عذاب نازل ہوتا','Had it not been for Allah’s grace and mercy upon you in this world and the Hereafter, you would have certainly been touched with a tremendous punishment for what you plunged into—','और अगर तुम लोगों पर दुनिया और आख़िरत में ख़ुदा का फज़ल (व करम) और उसकी रहमत न होती तो जिस बात का तुम लोगों ने चर्चा किया था उस की वजह से तुम पर कोई बड़ा (सख्त) अज़ाब आ पहुँचता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,15,'An-Noor','إِذۡ تَلَقَّوۡنَهُۥ بِأَلۡسِنَتِكُمۡ وَتَقُولُونَ بِأَفۡوَاهِكُم مَّا لَيۡسَ لَكُم بِهِۦ عِلۡمࣱ وَتَحۡسَبُونَهُۥ هَيِّنࣰ ا وَهُوَ عِندَ ٱللَّهِ عَظِيمࣱ‏','جب تم اپنی زبانوں سے اس کا ایک دوسرے سے ذکر کرتے تھے اور اپنے منہ سے ایسی بات کہتے تھے جس کا تم کو کچھ علم نہ تھا اور تم اسے ایک ہلکی بات سمجھتے تھے اور خدا کے نزدیک وہ بڑی بھاری بات تھی','when you passed it from one tongue to the other, and said with your mouths what you had no knowledge of, taking it lightly while it is ˹extremely˺ serious in the sight of Allah','कि तुम अपनी ज़बानों से इसको एक दूसरे से बयान करने लगे और अपने मुँह से ऐसी बात कहते थे जिसका तुम्हें इल्म व यक़ीन न था (और लुत्फ ये है कि) तुमने इसको एक आसान बात समझी थी हॉलाकि वह ख़ुदा के नज़दीक बड़ी सख्त बात थी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,16,'An-Noor','وَلَوۡلَآ إِذۡ سَمِعۡتُمُوهُ قُلۡتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبۡحَٰنَكَ هَٰذَا بُهۡتَٰنٌ عَظِيمࣱ‏','اور جب تم نے اسے سنا تھا تو کیوں نہ کہہ دیا کہ ہمیں شایاں نہیں کہ ایسی بات زبان پر نہ لائیں۔ (پروردگار) تو پاک ہے یہ تو (بہت) بڑا بہتان ہے','If only you had said upon hearing it, “How can we speak about such a thing! Glory be to You ˹O Lord˺! This is a heinous slander!”','और जब तुमने ऐसी बात सुनी थी तो तुमने लोगों से क्यों न कह दिया कि हमको ऐसी बात मुँह से निकालनी मुनासिब नहीं सुबहान अल्लाह ये बड़ा भारी बोहतान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,17,'An-Noor','يَعِظُكُمُ ٱللَّهُ أَن تَعُودُواْ لِمِثۡلِهِۦٓ أَبَدًا إِن كُنتُم مُّؤۡمِنِينَ','خدا تمہیں نصیحت کرتا ہے کہ اگر مومن ہو تو پھر کبھی ایسا کام نہ کرنا','Allah forbids you from ever doing something like this again, if you are ˹true˺ believers','ख़ुदा तुम्हारी नसीहत करता है कि अगर तुम सच्चे ईमानदार हो तो ख़बरदार फिर कभी ऐसा न करना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,18,'An-Noor','وَيُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌ','اور خدا تمہارے (سمجھانے کے لئے) اپنی آیتیں کھول کھول کر بیان فرماتا ہے۔ اور خدا جاننے والا حکمت والا ہے','And Allah makes ˹His˺ commandments clear to you, for Allah is All-Knowing, All-Wise','और ख़ुदा तुम से (अपने) एहकाम साफ साफ बयान करता है और ख़ुदा तो बड़ा वाक़िफकार हकीम है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,19,'An-Noor','إِنَّ ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلۡفَٰحِشَةُ فِي ٱلَّذِينَ ءَامَنُواْ لَهُمۡ عَذَابٌ أَلِيمࣱ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ','اور جو لوگ اس بات کو پسند کرتے ہیں کہ مومنوں میں بےحیائی یعنی (تہمت بدکاری کی خبر) پھیلے ان کو دنیا اور آخرت میں دکھ دینے والا عذاب ہوگا۔ اور خدا جانتا ہے اور تم نہیں جانتے','Indeed, those who love to see indecency spread among the believers will suffer a painful punishment in this life and the Hereafter. Allah knows and you do not know','जो लोग ये चाहते हैं कि ईमानदारों में बदकारी का चर्चा फैल जाए बेशक उनके लिए दुनिया और आख़िरत में दर्दनाक अज़ाब है और ख़ुदा (असल हाल को) ख़ूब जानता है और तुम लोग नहीं जानते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,20,'An-Noor','وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ وَأَنَّ ٱللَّهَ رَءُوفࣱ رَّحِيمࣱ‏','اور اگر تم پر خدا کا فضل اور اس کی رحمت نہ ہوتی (تو کیا کچھ نہ ہوتا مگر وہ کریم ہے) اور یہ کہ خدا نہایت مہربان اور رحیم ہے','˹You would have suffered,˺ had it not been for Allah’s grace and mercy upon you, and had Allah not been Ever Gracious, Most Merciful','और अगर ये बात न होती कि तुम पर ख़ुदा का फ़ज़ल (व करम) और उसकी रहमत से और ये कि ख़ुदा (अपने बन्दों पर) बड़ा शफीक़ मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,21,'An-Noor','۞يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ وَمَن يَتَّبِعۡ خُطُوَٰتِ ٱلشَّيۡطَٰنِ فَإِنَّهُۥ يَأۡمُرُ بِٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۚ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنۡ أَحَدٍ أَبَدࣰ ا وَلَٰكِنَّ ٱللَّهَ يُزَكِّي مَن يَشَآءُۗ وَٱللَّهُ سَمِيعٌ عَلِيمࣱ‏','اے مومنو! شیطان کے قدموں پر نہ چلنا۔ اور جو شخص شیطان کے قدموں پر چلے گا تو شیطان تو بےحیائی (کی باتیں) اور برے کام ہی بتائے گا۔ اور اگر تم پر خدا کا فضل اور اس کی مہربانی نہ ہوتی تو ایک شخص بھی تم میں پاک نہ ہوسکتا۔ مگر خدا جس کو چاہتا ہے پاک کردیتا ہے۔ اور خدا سننے والا (اور) جاننے والا ہے','O believers! Do not follow the footsteps of Satan. Whoever follows Satan’s footsteps, then ˹let them know that˺ he surely bids ˹all to˺ immorality and wickedness. Had it not been for Allah’s grace and mercy upon you, none of you would have ever been purified. But Allah purifies whoever He wills. And Allah is All-Hearing, All-Knowing','(तो तुम देखते क्या होता) ऐ ईमानदारों शैतान के क़दम ब क़दम न चलो और जो शख्स शैतान के क़दम ब क़दम चलेगा तो वह यक़ीनन उसे बदकारी और बुरी बात (करने) का हुक्म देगा और अगर तुम पर ख़ुदा का फ़ज़ल (व करम) और उसकी रहमत न होती तो तुममें से कोई भी कभी पाक साफ न होता मगर ख़ुदा तो जिसे चहता है पाक साफ कर देता है और ख़ुदा बड़ा सुनने वाला वाकिफकार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,22,'An-Noor','وَلَا يَأۡتَلِ أُوْلُواْ ٱلۡفَضۡلِ مِنكُمۡ وَٱلسَّعَةِ أَن يُؤۡتُوٓاْ أُوْلِي ٱلۡقُرۡبَىٰ وَٱلۡمَسَٰكِينَ وَٱلۡمُهَٰجِرِينَ فِي سَبِيلِ ٱللَّهِۖ وَلۡيَعۡفُواْ وَلۡيَصۡفَحُوٓاْۗ أَلَا تُحِبُّونَ أَن يَغۡفِرَ ٱللَّهُ لَكُمۡۚ وَٱللَّهُ غَفُورࣱ رَّحِيمٌ','اور جو لوگ تم میں صاحب فضل (اور صاحب) وسعت ہیں، وہ اس بات کی قسم نہ کھائیں کہ رشتہ داروں اور محتاجوں اور وطن چھوڑ جانے والوں کو کچھ خرچ پات نہیں دیں گے۔ ان کو چاہیئے کہ معاف کردیں اور درگزر کریں۔ کیا تم پسند نہیں کرتے کہ خدا تم کو بخش دے؟ اور خدا تو بخشنے والا مہربان ہے','Do not let the people of virtue and affluence among you swear to suspend donations to their relatives, the needy, and the emigrants in the cause of Allah. Let them pardon and forgive. Do you not love to be forgiven by Allah? And Allah is All-Forgiving, Most Merciful','और तुममें से जो लोग ज्यादा दौलत और मुक़द्दर वालें है क़राबतदारों और मोहताजों और ख़ुदा की राह में हिजरत करने वालों को कुछ देने (लेने) से क़सम न खा बैठें बल्कि उन्हें चाहिए कि (उनकी ख़ता) माफ कर दें और दरगुज़र करें क्या तुम ये नहीं चाहते हो कि ख़ुदा तुम्हारी ख़ता माफ करे और खुदा तो बड़ा बख्शने वाला मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,23,'An-Noor','إِنَّ ٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ٱلۡغَٰفِلَٰتِ ٱلۡمُؤۡمِنَٰتِ لُعِنُواْ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَلَهُمۡ عَذَابٌ عَظِيمࣱ‏','جو لوگ پرہیزگار اور برے کاموں سے بےخبر اور ایمان دار عورتوں پر بدکاری کی تہمت لگاتے ہیں ان پر دنیا وآخرت (دونوں) میں لعنت ہے۔ اور ان کو سخت عذاب ہوگا','Surely those who accuse chaste, unsuspecting, believing women are cursed in this life and the Hereafter. And they will suffer a tremendous punishment','बेशक जो लोग पाक दामन बेख़बर और ईमानदार औरतों पर (ज़िना की) तोहमत लगाते हैं उन पर दुनिया और आख़िरत में (ख़ुदा की) लानत है और उन पर बड़ा (सख्त) अज़ाब होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,24,'An-Noor','يَوۡمَ تَشۡهَدُ عَلَيۡهِمۡ أَلۡسِنَتُهُمۡ وَأَيۡدِيهِمۡ وَأَرۡجُلُهُم بِمَا كَانُواْ يَعۡمَلُونَ','(یعنی قیامت کے روز) جس دن ان کی زبانیں ہاتھ اور پاؤں سب ان کے کاموں کی گواہی دیں گے','on the Day their tongues, hands, and feet will testify against them for what they used to do','जिस दिन उनके ख़िलाफ उनकी ज़बानें और उनके हाथ उनके पावँ उनकी कारस्तानियों की गवाही देगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,25,'An-Noor','يَوۡمَئِذࣲ يُوَفِّيهِمُ ٱللَّهُ دِينَهُمُ ٱلۡحَقَّ وَيَعۡلَمُونَ أَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ ٱلۡمُبِينُ','اس دن خدا ان کو (ان کے اعمال کا) پورا پورا (اور) ٹھیک بدلہ دے گا اور ان کو معلوم ہوجائے گا کہ خدا برحق (اور حق کو) ظاہر کرنے والا ہے','On that Day, Allah will give them their just penalty in full, and they will ˹come to˺ know that Allah ˹alone˺ is the Ultimate Truth','उस दिन ख़ुदा उनको ठीक उनका पूरा पूरा बदला देगा और जान जाएँगें कि ख़ुदा बिल्कुल बरहक़ और (हक़ का) ज़ाहिर करने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,26,'An-Noor','ٱلۡخَبِيثَٰتُ لِلۡخَبِيثِينَ وَٱلۡخَبِيثُونَ لِلۡخَبِيثَٰتِۖ وَٱلطَّيِّبَٰتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَٰتِۚ أُوْلَٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَۖ لَهُم مَّغۡفِرَةࣱ وَرِزۡقࣱ كَرِيمࣱ‏','ناپاک عورتیں ناپاک مردوں کے لئے اور ناپاک مرد ناپاک عورتوں کے لئے۔ اور پاک عورتیں پاک مردوں کے لئے۔ اور پاک مرد پاک عورتوں کے لئے۔ یہ (پاک لوگ) ان (بدگویوں) کی باتوں سے بری ہیں (اور) ان کے لئے بخشش اور نیک روزی ہے','Wicked women are for wicked men, and wicked men are for wicked women. And virtuous women are for virtuous men, and virtuous men are for virtuous women. The virtuous are innocent of what the wicked say. They will have forgiveness and an honourable provision','गन्दी औरते गन्दें मर्दों के लिए (मुनासिब) हैं और गन्दे मर्द गन्दी औरतो के लिए और पाक औरतें पाक मर्दों के लिए (मौज़ूँ) हैं और पाक मर्द पाक औरतों के लिए लोग जो कुछ उनकी निस्बत बका करते हैं उससे ये लोग बुरी उल ज़िम्मा हैं उन ही (पाक लोगों) के लिए (आख़िरत में) बख़्शिस है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,27,'An-Noor','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتًا غَيۡرَ بُيُوتِكُمۡ حَتَّىٰ تَسۡتَأۡنِسُواْ وَتُسَلِّمُواْ عَلَىٰٓ أَهۡلِهَاۚ ذَٰلِكُمۡ خَيۡرࣱ لَّكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ','مومنو! اپنے گھروں کے سوا دوسرے (لوگوں کے) گھروں میں گھر والوں سے اجازت لئے اور ان کو سلام کئے بغیر داخل نہ ہوا کرو۔ یہ تمہارے حق میں بہتر ہے (اور ہم) یہ نصیحت اس لئے کرتے ہیں کہ شاید تم یاد رکھو','O believers! Do not enter any house other than your own until you have asked for permission and greeted its occupants. This is best for you, so perhaps you will be mindful','और इज्ज़त की रोज़ी ऐ ईमानदारों अपने घरों के सिवा दूसरे घरों में (दर्राना) न चले जाओ यहाँ तक कि उनसे इजाज़त ले लो और उन घरों के रहने वालों से साहब सलामत कर लो यही तुम्हारे हक़ में बेहतर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,28,'An-Noor','فَإِن لَّمۡ تَجِدُواْ فِيهَآ أَحَدࣰ ا فَلَا تَدۡخُلُوهَا حَتَّىٰ يُؤۡذَنَ لَكُمۡۖ وَإِن قِيلَ لَكُمُ ٱرۡجِعُواْ فَٱرۡجِعُواْۖ هُوَ أَزۡكَىٰ لَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمࣱ‏','اگر تم گھر میں کسی کو موجود نہ پاؤ تو جب تک تم کو اجازت نہ دی جائے اس میں مت داخل ہو۔ اور اگر یہ کہا جائے کہ (اس وقت) لوٹ جاؤ تو لوٹ جایا کرو۔ یہ تمہارے لئے بڑی پاکیزگی کی بات ہے۔ اور جو کام تم کرتے ہو خدا سب جانتا ہے','If you find no one at home, do not enter it until you have been given permission. And if you are asked to leave, then leave. That is purer for you. And Allah has ˹perfect˺ knowledge of what you do','(ये नसीहत इसलिए है) ताकि तुम याद रखो पस अगर तुम उन घरों में किसी को न पाओ तो तावाक़फियत कि तुम को (ख़ास तौर पर) इजाज़त न हासिल हो जाए उन में न जाओ और अगर तुम से कहा जाए कि फिर जाओ तो तुम (बे ताम्मुल) फिर जाओ यही तुम्हारे वास्ते ज्यादा सफाई की बात है और तुम जो कुछ भी करते हो ख़ुदा उससे खूब वाकिफ़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,29,'An-Noor','لَّيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَدۡخُلُواْ بُيُوتًا غَيۡرَ مَسۡكُونَةࣲ فِيهَا مَتَٰعࣱ لَّكُمۡۚ وَٱللَّهُ يَعۡلَمُ مَا تُبۡدُونَ وَمَا تَكۡتُمُونَ','ہاں اگر تم کسی ایسے مکان میں جاؤ جس میں کوئی نہ بستا ہو اور اس میں تمہارا اسباب (رکھا) ہو، تم پر کچھ گناہ نہیں، اور جو کچھ تم ظاہر کرتے ہو اور جو پوشیدہ کرتے ہو خدا کو سب معلوم ہے','There is no blame on you if you enter public places where there is something of benefit for you. And Allah knows what you reveal and what you conceal','इसमें अलबत्ता तुम पर इल्ज़ाम नहीं कि ग़ैर आबाद मकानात में जिसमें तुम्हारा कोई असबाब हो (बे इजाज़त) चले जाओ और जो कुछ खुल्लम खुल्ला करते हो और जो कुछ छिपाकर करते हो खुदा (सब कुछ) जानता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,30,'An-Noor','قُل لِّلۡمُؤۡمِنِينَ يَغُضُّواْ مِنۡ أَبۡصَٰرِهِمۡ وَيَحۡفَظُواْ فُرُوجَهُمۡۚ ذَٰلِكَ أَزۡكَىٰ لَهُمۡۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا يَصۡنَعُونَ','مومن مردوں سے کہہ دو کہ اپنی نظریں نیچی رکھا کریں اور اپنی شرم گاہوں کی حفاظت کیا کریں۔ یہ ان کے لئے بڑی پاکیزگی کی بات ہے اور جو کام یہ کرتے ہیں خدا ان سے خبردار ہے','˹O Prophet!˺ Tell the believing men to lower their gaze and guard their chastity. That is purer for them. Surely Allah is All-Aware of what they do','(ऐ रसूल) ईमानदारों से कह दो कि अपनी नज़रों को नीची रखें और अपनी शर्मगाहों की हिफाज़त करें यही उनके वास्ते ज्यादा सफाई की बात है ये लोग जो कुछ करते हैं ख़ुदा उससे यक़ीनन ख़ूब वाक़िफ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,31,'An-Noor','وَقُل لِّلۡمُؤۡمِنَٰتِ يَغۡضُضۡنَ مِنۡ أَبۡصَٰرِهِنَّ وَيَحۡفَظۡنَ فُرُوجَهُنَّ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنۡهَاۖ وَلۡيَضۡرِبۡنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّۖ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوۡ ءَابَآئِهِنَّ أَوۡ ءَابَآءِ بُعُولَتِهِنَّ أَوۡ أَبۡنَآئِهِنَّ أَوۡ أَبۡنَآءِ بُعُولَتِهِنَّ أَوۡ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ أَخَوَٰتِهِنَّ أَوۡ نِسَآئِهِنَّ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُنَّ أَوِ ٱلتَّٰبِعِينَ غَيۡرِ أُوْلِي ٱلۡإِرۡبَةِ مِنَ ٱلرِّجَالِ أَوِ ٱلطِّفۡلِ ٱلَّذِينَ لَمۡ يَظۡهَرُواْ عَلَىٰ عَوۡرَٰتِ ٱلنِّسَآءِۖ وَلَا يَضۡرِبۡنَ بِأَرۡجُلِهِنَّ لِيُعۡلَمَ مَا يُخۡفِينَ مِن زِينَتِهِنَّۚ وَتُوبُوٓاْ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِحُونَ','اور مومن عورتوں سے بھی کہہ دو کہ وہ بھی اپنی نگاہیں نیچی رکھا کریں اور اپنی شرم گاہوں کی حفاظت کیا کریں اور اپنی آرائش (یعنی زیور کے مقامات) کو ظاہر نہ ہونے دیا کریں مگر جو ان میں سے کھلا رہتا ہو۔ اور اپنے سینوں پر اوڑھنیاں اوڑھے رہا کریں اور اپنے خاوند اور باپ اور خسر اور بیٹیوں اور خاوند کے بیٹوں اور بھائیوں اور بھتیجیوں اور بھانجوں اور اپنی (ہی قسم کی) عورتوں اور لونڈی غلاموں کے سوا نیز ان خدام کے جو عورتوں کی خواہش نہ رکھیں یا ایسے لڑکوں کے جو عورتوں کے پردے کی چیزوں سے واقف نہ ہوں (غرض ان لوگوں کے سوا) کسی پر اپنی زینت (اور سنگار کے مقامات) کو ظاہر نہ ہونے دیں۔ اور اپنے پاؤں (ایسے طور سے زمین پر) نہ ماریں (کہ جھنکار کانوں میں پہنچے اور) ان کا پوشیدہ زیور معلوم ہوجائے۔ اور مومنو! سب خدا کے آگے توبہ کرو تاکہ فلاح پاؤ','And tell the believing women to lower their gaze and guard their chastity, and not to reveal their adornments except what normally appears. Let them draw their veils over their chests, and not reveal their ˹hidden˺ adornments except to their husbands, their fathers, their fathers-in-law, their sons, their stepsons, their brothers, their brothers’ sons or sisters’ sons, their fellow women, those ˹bondwomen˺ in their possession, male attendants with no desire, or children who are still unaware of women’s nakedness. Let them not stomp their feet, drawing attention to their hidden adornments. Turn to Allah in repentance all together, O believers, so that you may be successful','और (ऐ रसूल) ईमानदार औरतों से भी कह दो कि वह भी अपनी नज़रें नीची रखें और अपनी शर्मगाहों की हिफाज़त करें और अपने बनाव सिंगार (के मक़ामात) को (किसी पर) ज़ाहिर न होने दें मगर जो खुद ब खुद ज़ाहिर हो जाता हो (छुप न सकता हो) (उसका गुनाह नही) और अपनी ओढ़नियों को (घूँघट मारके) अपने गरेबानों (सीनों) पर डाले रहें और अपने शौहर या अपने बाप दादाओं या आपने शौहर के बाप दादाओं या अपने बेटों या अपने शौहर के बेटों या अपने भाइयों या अपने भतीजों या अपने भांजों या अपने (क़िस्म की) औरतों या अपनी या अपनी लौंडियों या (घर के) नौकर चाकर जो मर्द सूरत हैं मगर (बहुत बूढे होने की वजह से) औरतों से कुछ मतलब नहीं रखते या वह कमसिन लड़के जो औरतों के पर्दे की बात से आगाह नहीं हैं उनके सिवा (किसी पर) अपना बनाव सिंगार ज़ाहिर न होने दिया करें और चलने में अपने पाँव ज़मीन पर इस तरह न रखें कि लोगों को उनके पोशीदा बनाव सिंगार (झंकार वग़ैरह) की ख़बर हो जाए और ऐ ईमानदारों तुम सबके सब ख़ुदा की बारगाह में तौबा करो ताकि तुम फलाह पाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,32,'An-Noor','وَأَنكِحُواْ ٱلۡأَيَٰمَىٰ مِنكُمۡ وَٱلصَّٰلِحِينَ مِنۡ عِبَادِكُمۡ وَإِمَآئِكُمۡۚ إِن يَكُونُواْ فُقَرَآءَ يُغۡنِهِمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱللَّهُ وَٰسِعٌ عَلِيمࣱ‏','اور اپنی قوم کی بیوہ عورتوں کے نکاح کردیا کرو۔ اور اپنے غلاموں اور لونڈیوں کے بھی جو نیک ہوں (نکاح کردیا کرو) اگر وہ مفلس ہوں گے تو خدا ان کو اپنے فضل سے خوش حال کردے گا۔ اور خدا (بہت) وسعت والا اور (سب کچھ) جاننے والا ہے','Marry off the ˹free˺ singles among you, as well as the righteous of your bondmen and bondwomen. If they are poor, Allah will enrich them out of His bounty. For Allah is All-Bountiful, All-Knowing','और अपनी (क़ौम की) बेशौहर औरतों और अपने नेक बख्त गुलामों और लौंडियों का निकाह कर दिया करो अगर ये लोग मोहताज होंगे तो खुदा अपने फज़ल व (करम) से उन्हें मालदार बना देगा और ख़ुदा तो बड़ी गुन्जाइश वाला वाक़िफ कार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,33,'An-Noor','وَلۡيَسۡتَعۡفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغۡنِيَهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱلَّذِينَ يَبۡتَغُونَ ٱلۡكِتَٰبَ مِمَّا مَلَكَتۡ أَيۡمَٰنُكُمۡ فَكَاتِبُوهُمۡ إِنۡ عَلِمۡتُمۡ فِيهِمۡ خَيۡرࣰ اۖ وَءَاتُوهُم مِّن مَّالِ ٱللَّهِ ٱلَّذِيٓ ءَاتَىٰكُمۡۚ وَلَا تُكۡرِهُواْ فَتَيَٰتِكُمۡ عَلَى ٱلۡبِغَآءِ إِنۡ أَرَدۡنَ تَحَصُّنࣰ ا لِّتَبۡتَغُواْ عَرَضَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَمَن يُكۡرِههُّنَّ فَإِنَّ ٱللَّهَ مِنۢ بَعۡدِ إِكۡرَٰهِهِنَّ غَفُورࣱ رَّحِيمࣱ‏','اور جن کو بیاہ کا مقدور نہ ہو وہ پاک دامنی کو اختیار کئے رہیں یہاں تک کہ خدا ان کو اپنے فضل سے غنی کردے۔ اور جو غلام تم سے مکاتبت چاہیں اگر تم ان میں (صلاحیت اور) نیکی پاؤ تو ان سے مکاتبت کرلو۔ اور خدا نے جو مال تم کو بخشا ہے اس میں سے ان کو بھی دو۔ اور اپنی لونڈیوں کو اگر وہ پاک دامن رہنا چاہیں تو (بےشرمی سے) دنیاوی زندگی کے فوائد حاصل کرنے کے لئے بدکاری پر مجبور نہ کرنا۔ اور جو ان کو مجبور کرے گا تو ان (بیچاریوں) کے مجبور کئے جانے کے بعد خدا بخشنے والا مہربان ہے','And let those who do not have the means to marry keep themselves chaste until Allah enriches them out of His bounty. And if any of those ˹bondspeople˺ in your possession desires a deed of emancipation, make it possible for them, if you find goodness in them. And give them some of Allah’s wealth which He has granted you. Do not force your ˹slave˺ girls into prostitution for your own worldly gains while they wish to remain chaste. And if someone coerces them, then after such a coercion Allah is certainly All-Forgiving, Most Merciful ˹to them˺','और जो लोग निकाह करने का मक़दूर नहीं रखते उनको चाहिए कि पाक दामिनी एख्तियार करें यहाँ तक कि ख़ुदा उनको अपने फज़ल व (करम) से मालदार बना दे और तुम्हारी लौन्डी ग़ुलामों में से जो मकातबत होने (कुछ रुपए की शर्त पर आज़ादी का सरख़त लेने) की ख्वाहिश करें तो तुम अगर उनमें कुछ सलाहियत देखो तो उनको मकातिब कर दो और ख़ुदा के माल से जो उसने तुम्हें अता किया है उनका भी दो और तुम्हारी लौन्डियाँ जो पाक दामन ही रहना चाहती हैं उनको दुनियावी ज़िन्दगी के फायदे हासिल करने की ग़रज़ से हराम कारी पर मजबूर न करो और जो शख्स उनको मजबूर करेगा तो इसमें शक नहीं कि ख़ुदा उसकी बेबसी के बाद बड़ा बख्शने वाले मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,34,'An-Noor','وَلَقَدۡ أَنزَلۡنَآ إِلَيۡكُمۡ ءَايَٰتࣲ مُّبَيِّنَٰتࣲ وَمَثَلࣰ ا مِّنَ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِكُمۡ وَمَوۡعِظَةࣰ لِّلۡمُتَّقِينَ','اور ہم نے تمہاری طرف روشن آیتیں نازل کی ہیں اور جو لوگ تم سے پہلے گزر چکے ہیں ان کی خبریں اور پرہیزگاروں کے لئے نصیحت','Indeed, We have sent down to you clear revelations, along with examples of those who had gone before you, and a lesson to the God-fearing','और (ईमानदारों) हमने तो तुम्हारे पास (अपनी) वाज़ेए व रौशन आयतें और जो लोग तुमसे पहले गुज़र चुके हैं उनकी हालतें और परहेज़गारों के लिए नसीहत (की बाते) नाज़िल की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,35,'An-Noor','۞ٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ مَثَلُ نُورِهِۦ كَمِشۡكَوٰةࣲ فِيهَا مِصۡبَاحٌۖ ٱلۡمِصۡبَاحُ فِي زُجَاجَةٍۖ ٱلزُّجَاجَةُ كَأَنَّهَا كَوۡكَبࣱ دُرِّيࣱّ يُوقَدُ مِن شَجَرَةࣲ مُّبَٰرَكَةࣲ زَيۡتُونَةࣲ لَّا شَرۡقِيَّةࣲ وَلَا غَرۡبِيَّةࣲ يَكَادُ زَيۡتُهَا يُضِيٓءُ وَلَوۡ لَمۡ تَمۡسَسۡهُ نَارࣱۚ نُّورٌ عَلَىٰ نُورࣲۚ يَهۡدِي ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُۚ وَيَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَٰلَ لِلنَّاسِۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمࣱ‏','خدا آسمانوں اور زمین کا نور ہے۔ اس کے نور کی مثال ایسی ہے کہ گویا ایک طاق ہے جس میں چراغ ہے۔ اور چراغ ایک قندیل میں ہے۔ اور قندیل (ایسی صاف شفاف ہے کہ) گویا موتی کا سا چمکتا ہوا تارہ ہے اس میں ایک مبارک درخت کا تیل جلایا جاتا ہے (یعنی) زیتون کہ نہ مشرق کی طرف ہے نہ مغرب کی طرف۔ (ایسا معلوم ہوتا ہے کہ) اس کا تیل خواہ آگ اسے نہ بھی چھوئے جلنے کو تیار ہے (پڑی) روشنی پر روشنی (ہو رہی ہے) خدا اپنے نور سے جس کو چاہتا ہے سیدھی راہ دکھاتا ہے۔ اور خدا نے (جو مثالیں) بیان فرماتا ہے (تو) لوگوں کے (سمجھانے کے) لئے اور خدا ہر چیز سے واقف ہے','Allah is the Light of the heavens and the earth. His light is like a niche in which there is a lamp, the lamp is in a crystal, the crystal is like a shining star, lit from ˹the oil of˺ a blessed olive tree, ˹located˺ neither to the east nor the west, whose oil would almost glow, even without being touched by fire. Light upon light! Allah guides whoever He wills to His light. And Allah sets forth parables for humanity. For Allah has ˹perfect˺ knowledge of all things','ख़ुदा तो सारे आसमान और ज़मीन का नूर है उसके नूर की मिसल (ऐसी) है जैसे एक ताक़ (सीना) है जिसमे एक रौशन चिराग़ (इल्मे शरीयत) हो और चिराग़ एक शीशे की क़न्दील (दिल) में हो (और) क़न्दील (अपनी तड़प में) गोया एक जगमगाता हुआ रौशन सितारा (वह चिराग़) जैतून के मुबारक दरख्त (के तेल) से रौशन किया जाए जो न पूरब की तरफ हो और न पश्चिम की तरफ (बल्कि बीचों बीच मैदान में) उसका तेल (ऐसा) शफ्फाफ हो कि अगरचे आग उसे छुए भी नही ताहम ऐसा मालूम हो कि आप ही आप रौशन हो जाएगा (ग़रज़ एक नूर नहीं बल्कि) नूर आला नूर (नूर की नूर पर जोत पड़ रही है) ख़ुदा अपने नूर की तरफ जिसे चाहता है हिदायत करता है और ख़ुदा तो हर चीज़ से खूब वाक़िफ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,36,'An-Noor','فِي بُيُوتٍ أَذِنَ ٱللَّهُ أَن تُرۡفَعَ وَيُذۡكَرَ فِيهَا ٱسۡمُهُۥ يُسَبِّحُ لَهُۥ فِيهَا بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ','(وہ قندیل) ان گھروں میں (ہے) جن کے بارے میں خدا نے ارشاد فرمایا ہے کہ بلند کئے جائیں اور وہاں خدا کے نام کا ذکر کیا جائے (اور) ان میں صبح وشام اس کی تسبیح کرتے رہیں','˹That light shines˺ through houses ˹of worship˺ which Allah has ordered to be raised, and where His Name is mentioned. He is glorified there morning and evening','(वह क़न्दील) उन घरों में रौशन है जिनकी निस्बत ख़ुदा ने हुक्म दिया कि उनकी ताज़ीम की जाए और उनमें उसका नाम लिया जाए जिनमें सुबह व शाम वह लोग उसकी तस्बीह किया करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (24,37,'An-Noor','رِجَالࣱ لَّا تُلۡهِيهِمۡ تِجَٰرَةࣱ وَلَا بَيۡعٌ عَن ذِكۡرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ يَخَافُونَ يَوۡمࣰ ا تَتَقَلَّبُ فِيهِ ٱلۡقُلُوبُ وَٱلۡأَبۡصَٰرُ','(یعنی ایسے) لوگ جن کو خدا کے ذکر اور نماز پڑھنے اور زکوٰة دینے سے نہ سوداگری غافل کرتی ہے نہ خرید وفروخت۔ وہ اس دن سے جب دل (خوف اور گھبراہٹ کے سبب) الٹ جائیں گے اور آنکھیں (اوپر کو چڑھ جائیں گی) ڈرتے ہیں','by men who are not distracted—either by buying or selling—from Allah’s remembrance, or performing prayer, or paying alms-tax. They fear a Day when hearts and eyes will tremble','ऐसे लोग जिनको ख़ुदा के ज़िक्र और नमाज़ पढ़ने और ज़कात अदा करने से न तो तिजारत ही ग़ाफिल कर सकती है न (ख़रीद फरोख्त) (का मामला क्योंकि) वह लोग उस दिन से डरते हैं जिसमें ख़ौफ के मारे दिल और ऑंखें उलट जाएँगी');
